export { R, W };
R["csi-checkpoint-m1-task"] = "public class Solution\n{\n    public static bool IsSameInstance(object? a, object? b)\n    {\n        if (a is null || b is null) return false;\n        return ReferenceEquals(a, b);\n    }\n\n    public static string Classify(string? input) => input switch\n    {\n        null => \"empty\",\n        var s when string.IsNullOrWhiteSpace(s) => \"blank\",\n        var s when int.TryParse(s, out int n) => \"int:\" + n,\n        var s => \"text:\" + s,\n    };\n\n    public static (int Min, int Max) Range(IEnumerable<int>? numbers)\n    {\n        if (numbers is null) return (0, 0);\n        int min = int.MaxValue, max = int.MinValue;\n        foreach (int n in numbers)\n        {\n            if (n < min) min = n;\n            if (n > max) max = n;\n        }\n        return min == int.MaxValue ? (0, 0) : (min, max);\n    }\n}\n";
W["csi-checkpoint-m1-task"] = "public class Solution\n{\n    public static bool IsSameInstance(object? a, object? b)\n    {\n        // near-miss: Equals compares by VALUE \u2014 equal-but-distinct boxes\n        // wrongly report \"same instance\"\n        if (a is null || b is null) return false;\n        return a.Equals(b);\n    }\n\n    public static string Classify(string? input) => input switch\n    {\n        // near-miss: blank check before null \u2014 null dereferences inside\n        // IsNullOrWhiteSpace is fine, but null is classified \"blank\" not \"empty\"\n        var s when string.IsNullOrWhiteSpace(s) => \"blank\",\n        null => \"empty\",\n        var s when int.TryParse(s, out int n) => \"int:\" + n,\n        var s => \"text:\" + s,\n    };\n\n    public static (int Min, int Max) Range(IEnumerable<int>? numbers)\n    {\n        // near-miss: Min()/Max() throw on empty \u2014 and null was \"fixed\" with !\n        if (numbers is null) return (0, 0);\n        return (numbers.Min(), numbers.Max());\n    }\n}\n";
R["csi-p1-copy-alias"] = "public class Solution\n{\n    public record struct ValuePoint(int X);\n    public record class RefPoint(int X);\n\n    public static ValuePoint BumpValue(ValuePoint p)\n    {\n        p.X = p.X + 1;\n        return p;\n    }\n\n    public static RefPoint BumpRef(RefPoint p)\n    {\n        p.X = p.X + 1;\n        return p;\n    }\n}\n";
W["csi-p1-copy-alias"] = "public class Solution\n{\n    public record struct ValuePoint(int X);\n    public record class RefPoint(int X);\n\n    // near-miss: reassigns the parameter to a NEW RefPoint \u2014 the caller's\n    // object is untouched, so the alias test fails\n    public static ValuePoint BumpValue(ValuePoint p)\n    {\n        p.X = p.X + 1;\n        return p;\n    }\n\n    public static RefPoint BumpRef(RefPoint p)\n    {\n        p = new RefPoint(p.X + 1);\n        return p;\n    }\n}\n";
