W["csi-p1-boxing-prediction"] = "public class Solution\n{\n    public static bool SameBox(object a, object b)\n    {\n        // near-miss: Equals compares boxed VALUES \u2014 equal ints in distinct\n        // boxes wrongly count as the \"same box\"\n        return a.Equals(b);\n    }\n\n    public static T UnboxAs<T>(object boxed) where T : struct\n        => (T)boxed;\n\n    public static long SumNoBox(int[] values)\n    {\n        long total = 0;\n        foreach (object v in values) total += Convert.ToInt64(v);\n        return total;\n    }\n}\n";
R["csi-p1-nullable-fix"] = "public class Solution\n{\n    public static int? ParsePositive(string? input)\n    {\n        if (string.IsNullOrWhiteSpace(input)) return null;\n        if (!int.TryParse(input.Trim(), out int n)) return null;\n        return n > 0 ? n : null;\n    }\n\n    public static string? FirstAbove(Dictionary<string, int> scores, int threshold)\n    {\n        foreach (var (name, score) in scores)\n        {\n            if (score > threshold) return name;\n        }\n        return null;\n    }\n\n    public static string DisplayName(string? name)\n    {\n        if (string.IsNullOrWhiteSpace(name)) return \"guest\";\n        return name.Trim();\n    }\n}\n";
