R["csi-p1-switch-describe"] = "public class Solution\n{\n    public static string SizeClass(int n) => n switch\n    {\n        < 0 => \"neg\",\n        0 => \"zero\",\n        > 0 and < 100 => \"small\",\n        _ => \"large\",\n    };\n\n    public static string Vote(string? answer) => answer?.ToLowerInvariant() switch\n    {\n        \"yes\" or \"no\" or \"maybe\" => \"ok\",\n        _ => \"unknown\",\n    };\n\n    public static string Zone(bool hasTicket, bool isVip, int age) =>\n        (hasTicket, isVip, age) switch\n        {\n            (_, true, _) => \"gold\",\n            (true, false, >= 18) => \"standard\",\n            (true, false, _) => \"minor\",\n            _ => \"deny\",\n        };\n}\n";
W["csi-p1-switch-describe"] = "public class Solution\n{\n    public static string SizeClass(int n) => n switch\n    {\n        < 0 => \"neg\",\n        0 => \"zero\",\n        > 0 and <= 100 => \"small\",   // near-miss: 100 now lands in \"small\"\n        _ => \"large\",\n    };\n\n    public static string Vote(string? answer) => answer?.ToLowerInvariant() switch\n    {\n        \"yes\" or \"no\" or \"maybe\" => \"ok\",\n        _ => \"unknown\",\n    };\n\n    public static string Zone(bool hasTicket, bool isVip, int age) =>\n        (hasTicket, isVip, age) switch\n        {\n            // near-miss: ticket rows before vip \u2014 a vip WITHOUT a ticket\n            // wrongly lands in \"minor\"/\"deny\"\n            (true, _, >= 18) => \"standard\",\n            (true, _, _) => \"minor\",\n            (_, true, _) => \"gold\",\n            _ => \"deny\",\n        };\n}\n";
R["csi-p1-deconstruct-report"] = "public class Solution\n{\n    public static (int Income, int Expense) Split(int[] signedEntries)\n    {\n        int income = 0, expense = 0;\n        foreach (int n in signedEntries)\n        {\n            if (n >= 0) income += n;\n            else expense += -n;\n        }\n        return (income, expense);\n    }\n\n    public static (int Value, int Index) FirstMax(int[] values)\n    {\n        if (values.Length == 0) return (0, -1);\n        int best = values[0], bestIndex = 0;\n        for (int i = 1; i < values.Length; i++)\n        {\n            if (values[i] > best)\n            {\n                best = values[i];\n                bestIndex = i;\n            }\n        }\n        return (best, bestIndex);\n    }\n\n    public sealed record Split10(int N)\n    {\n        public void Deconstruct(out int whole, out int remainder)\n        {\n            whole = N / 10;\n            remainder = N % 10;\n        }\n    }\n}\n";
W["csi-p1-deconstruct-report"] = "public class Solution\n{\n    public static (int Income, int Expense) Split(int[] signedEntries)\n    {\n        int income = 0, expense = 0;\n        foreach (int n in signedEntries)\n        {\n            // near-miss: 0 counted as expense \u2014 zeros are neither income\n            // nor debt, and the empty-like input now reports expense 0 anyway,\n            // but mixed inputs with zeros corrupt the totals\n            if (n > 0) income += n;\n            else expense += -n;\n        }\n        return (income, expense);\n    }\n\n    public static (int Value, int Index) FirstMax(int[] values)\n    {\n        if (values.Length == 0) return (0, -1);\n        int best = values[0], bestIndex = 0;\n        for (int i = 1; i < values.Length; i++)\n        {\n            // near-miss: >= drifts the index to the LAST max\n            if (values[i] >= best)\n            {\n                best = values[i];\n                bestIndex = i;\n            }\n        }\n        return (best, bestIndex);\n    }\n\n    public sealed record Split10(int N)\n    {\n        public void Deconstruct(out int whole, out int remainder)\n        {\n            whole = N / 10;\n            remainder = N % 10;\n        }\n    }\n}\n";
