R["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a > 0 && b > 0;\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        if (depth <= 0 || groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        if (depth > 1)\n        {\n            total += FlattenDepth(groups, depth - 1) == total ? 0 : 0;\n        }\n        return total;\n    }\n}\n";
W["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        // near-miss: forgot to assign out params on the early-return paths \u2014\n        // the compiler rejects this shape, so the W here instead accepts zero\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a >= 0 && b >= 0;   // near-miss: zero passes\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        // near-miss: no depth bound \u2014 recursion never terminates on the\n        // depth>=1 path unless the arrays are empty, so the deep test hangs\n        if (groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        return total + FlattenDepth(groups, depth - 1);\n    }\n}\n";
R["csi-checkpoint-m3-task"] = "public class Solution\n{\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        int total = seed;\n        return add => total += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
W["csi-checkpoint-m3-task"] = "public class Solution\n{\n    // near-miss: ONE static total shared by all accumulators \u2014 the\n    // independence test fails because acc2 keeps counting acc1's total\n    private static int _shared;\n\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        _shared = seed;\n        return add => _shared += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
R["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n            _nextId++;\n            if (filter is null || filter(message))\n            {\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, args);\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
W["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            // near-miss: the id counter only advances for ACCEPTED messages,\n            // so the filtered publish reuses n-1 and later ids shift\n            if (filter is null || filter(message))\n            {\n                var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n                _nextId++;\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, new NotificationEventArgs(\"n-\" + _nextId, channel, message));\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
