W["csi-p1-switch-describe"] = "public class Solution\n{\n    public static string SizeClass(int n) => n switch\n    {\n        < 0 => \"neg\",\n        0 => \"zero\",\n        > 0 and <= 100 => \"small\",   // near-miss: 100 now lands in \"small\"\n        _ => \"large\",\n    };\n\n    public static string Vote(string? answer) => answer?.ToLowerInvariant() switch\n    {\n        \"yes\" or \"no\" or \"maybe\" => \"ok\",\n        _ => \"unknown\",\n    };\n\n    public static string Zone(bool hasTicket, bool isVip, int age) =>\n        (hasTicket, isVip, age) switch\n        {\n            // near-miss: ticket rows before vip \u2014 a vip WITHOUT a ticket\n            // wrongly lands in \"minor\"/\"deny\"\n            (true, _, >= 18) => \"standard\",\n            (true, _, _) => \"minor\",\n            (_, true, _) => \"gold\",\n            _ => \"deny\",\n        };\n}\n";
R["csi-p1-deconstruct-report"] = "public class Solution\n{\n    public static (int Income, int Expense) Split(int[] signedEntries)\n    {\n        int income = 0, expense = 0;\n        foreach (int n in signedEntries)\n        {\n            if (n >= 0) income += n;\n            else expense += -n;\n        }\n        return (income, expense);\n    }\n\n    public static (int Value, int Index) FirstMax(int[] values)\n    {\n        if (values.Length == 0) return (0, -1);\n        int best = values[0], bestIndex = 0;\n        for (int i = 1; i < values.Length; i++)\n        {\n            if (values[i] > best)\n            {\n                best = values[i];\n                bestIndex = i;\n            }\n        }\n        return (best, bestIndex);\n    }\n\n    public sealed record Split10(int N)\n    {\n        public void Deconstruct(out int whole, out int remainder)\n        {\n            whole = N / 10;\n            remainder = N % 10;\n        }\n    }\n}\n";
W["csi-p1-deconstruct-report"] = "public class Solution\n{\n    public static (int Income, int Expense) Split(int[] signedEntries)\n    {\n        int income = 0, expense = 0;\n        foreach (int n in signedEntries)\n        {\n            // near-miss: 0 counted as expense \u2014 zeros are neither income\n            // nor debt, and the empty-like input now reports expense 0 anyway,\n            // but mixed inputs with zeros corrupt the totals\n            if (n > 0) income += n;\n            else expense += -n;\n        }\n        return (income, expense);\n    }\n\n    public static (int Value, int Index) FirstMax(int[] values)\n    {\n        if (values.Length == 0) return (0, -1);\n        int best = values[0], bestIndex = 0;\n        for (int i = 1; i < values.Length; i++)\n        {\n            // near-miss: >= drifts the index to the LAST max\n            if (values[i] >= best)\n            {\n                best = values[i];\n                bestIndex = i;\n            }\n        }\n        return (best, bestIndex);\n    }\n\n    public sealed record Split10(int N)\n    {\n        public void Deconstruct(out int whole, out int remainder)\n        {\n            whole = N / 10;\n            remainder = N % 10;\n        }\n    }\n}\n";
R["csi-checkpoint-m7-task"] = "public class Solution\n{\n    public static IEnumerable<(int Level, string Msg)> ParseLines(IEnumerable<string> lines)\n    {\n        foreach (string line in lines)\n        {\n            string[] parts = line.Split('|');\n            int level = parts[0] switch\n            {\n                \"DEBUG\" => 0,\n                \"INFO\" => 1,\n                \"WARN\" => 2,\n                \"ERROR\" => 3,\n                _ => 0,\n            };\n            yield return (level, parts[1]);\n        }\n    }\n\n    public static IEnumerable<(int Level, string Msg)> FilterLevel(\n        IEnumerable<(int Level, string Msg)> src, int minLevel)\n    {\n        foreach (var entry in src)\n            if (entry.Level >= minLevel) yield return entry;\n    }\n\n    public static IEnumerable<string> Format(IEnumerable<(int Level, string Msg)> src)\n    {\n        foreach (var entry in src)\n            yield return \"[\" + entry.Level + \"] \" + entry.Msg;\n    }\n\n    public static List<string> Run(IEnumerable<string> lines, int minLevel, int maxResults)\n    {\n        var output = new List<string>();\n        foreach (string formatted in Format(FilterLevel(ParseLines(lines), minLevel)))\n        {\n            output.Add(formatted);\n            if (output.Count >= maxResults) break;   // stop pulling from the source\n        }\n        return output;\n    }\n\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<string>\n    {\n        private readonly string[] _lines;\n\n        public CountingSource(params string[] lines) => _lines = lines;\n\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<string> GetEnumerator()\n        {\n            foreach (string line in _lines)\n            {\n                ReadCount++;\n                yield return line;\n            }\n        }\n    }\n}\n";
W["csi-checkpoint-m7-task"] = "public class Solution\n{\n    public static IEnumerable<(int Level, string Msg)> ParseLines(IEnumerable<string> lines)\n    {\n        foreach (string line in lines)\n        {\n            string[] parts = line.Split('|');\n            int level = parts[0] switch\n            {\n                \"DEBUG\" => 0,\n                \"INFO\" => 1,\n                \"WARN\" => 2,\n                \"ERROR\" => 3,\n                _ => 0,\n            };\n            yield return (level, parts[1]);\n        }\n    }\n\n    public static IEnumerable<(int Level, string Msg)> FilterLevel(\n        IEnumerable<(int Level, string Msg)> src, int minLevel)\n    {\n        foreach (var entry in src)\n            if (entry.Level >= minLevel) yield return entry;\n    }\n\n    public static IEnumerable<string> Format(IEnumerable<(int Level, string Msg)> src)\n    {\n        foreach (var entry in src)\n            yield return \"[\" + entry.Level + \"] \" + entry.Msg;\n    }\n\n    public static List<string> Run(IEnumerable<string> lines, int minLevel, int maxResults)\n    {\n        // near-miss: materializes the WHOLE pipeline before capping \u2014 the\n        // source is drained completely, so the laziness test fails\n        var everything = Format(FilterLevel(ParseLines(lines), minLevel)).ToList();\n        return everything.Take(maxResults).ToList();\n    }\n\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<string>\n    {\n        private readonly string[] _lines;\n\n        public CountingSource(params string[] lines) => _lines = lines;\n\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<string> GetEnumerator()\n        {\n            foreach (string line in _lines)\n            {\n                ReadCount++;\n                yield return line;\n            }\n        }\n    }\n}\n";
R["csi-p8-top-customers"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> TopCustomers(IEnumerable<OrderLine> lines, int n)\n    {\n        return lines\n            .GroupBy(l => l.Customer)\n            .Select(g => new { Name = g.Key, Total = g.Sum(l => l.Amount) })\n            .OrderByDescending(x => x.Total)\n            .ThenBy(x => x.Name)\n            .Take(n)\n            .Select(x => x.Name + \": \" + x.Total)\n            .ToList();\n    }\n}\n";
W["csi-p8-top-customers"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> TopCustomers(IEnumerable<OrderLine> lines, int n)\n    {\n        // near-miss: no ThenBy \u2014 OrderByDescending alone is NOT stable for\n        // equal keys in LINQ-to-objects group ordering, so the tie test fails\n        return lines\n            .GroupBy(l => l.Customer)\n            .Select(g => new { Name = g.Key, Total = g.Sum(l => l.Amount) })\n            .OrderByDescending(x => x.Total)\n            .Take(n)\n            .Select(x => x.Name + \": \" + x.Total)\n            .ToList();\n    }\n}\n";
R["csi-p8-group-report"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> DailyReport(IEnumerable<OrderLine> lines)\n    {\n        return lines\n            .GroupBy(l => l.Day)\n            .OrderBy(g => g.Key)\n            .Select(g =>\n            {\n                decimal avg = Math.Round(g.Average(l => l.Amount), 1, MidpointRounding.AwayFromZero);\n                return \"Day \" + g.Key.ToString(\"00\") + \": \" + g.Count() + \" orders, avg \" + avg.ToString(\"0.0\", System.Globalization.CultureInfo.InvariantCulture);\n            })\n            .ToList();\n    }\n}\n";
W["csi-p8-group-report"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> DailyReport(IEnumerable<OrderLine> lines)\n    {\n        // near-miss: forgot OrderBy(g => g.Key) \u2014 dictionary-group enumeration\n        // order happens to look sorted for this input but the explicit ordering\n        // contract is broken; the reversed-days test fails\n        return lines\n            .GroupBy(l => l.Day)\n            .Select(g =>\n            {\n                decimal avg = Math.Round(g.Average(l => l.Amount), 1, MidpointRounding.AwayFromZero);\n                return \"Day \" + g.Key.ToString(\"00\") + \": \" + g.Count() + \" orders, avg \" + avg.ToString(\"0.0\", System.Globalization.CultureInfo.InvariantCulture);\n            })\n            .ToList();\n    }\n}\n";
R["csi-p8-double-enum-debug"] = "public class Solution\n{\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<int>\n    {\n        private readonly int[] _items;\n        public CountingSource(params int[] items) => _items = items;\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<int> GetEnumerator()\n        {\n            foreach (int item in _items)\n            {\n                ReadCount++;\n                yield return item;\n            }\n        }\n    }\n\n    public static string Run(System.Collections.Generic.IEnumerable<int> source)\n    {\n        // fixed: ONE enumeration \u2014 materialize first, then aggregate freely\n        var data = source.ToList();\n        int count = data.Count;\n        int max = count > 0 ? data.Max() : 0;\n        return \"count=\" + count + \";max=\" + max;\n    }\n}\n";
W["csi-p8-double-enum-debug"] = "public class Solution\n{\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<int>\n    {\n        private readonly int[] _items;\n        public CountingSource(params int[] items) => _items = items;\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<int> GetEnumerator()\n        {\n            foreach (int item in _items)\n            {\n                ReadCount++;\n                yield return item;\n            }\n        }\n    }\n\n    public static string Run(System.Collections.Generic.IEnumerable<int> source)\n    {\n        // near-miss: still TWO passes over the lazy source \u2014 Count() pulls\n        // everything once, Max() pulls it all again; ReadCount == 12 for the\n        // six-item test\n        int count = source.Count();\n        int max = count > 0 ? source.Max() : 0;\n        return \"count=\" + count + \";max=\" + max;\n    }\n}\n";
R["csi-checkpoint-m8-task"] = "public class Solution\n{\n    public record Sale(string Customer, string Category, decimal Amount);\n\n    public sealed class CountingSales : System.Collections.Generic.IEnumerable<Sale>\n    {\n        private readonly Sale[] _sales;\n        public CountingSales(params Sale[] sales) => _sales = sales;\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<Sale> GetEnumerator()\n        {\n            foreach (Sale s in _sales)\n            {\n                ReadCount++;\n                yield return s;\n            }\n        }\n    }\n\n    public static decimal Revenue(System.Collections.Generic.IEnumerable<Sale> sales) =>\n        sales.Sum(s => s.Amount);\n\n    public static string BestCategory(System.Collections.Generic.IEnumerable<Sale> sales) =>\n        sales\n            .GroupBy(s => s.Category)\n            .Select(g => new { Category = g.Key, Total = g.Sum(s => s.Amount) })\n            .OrderByDescending(x => x.Total)\n            .ThenBy(x => x.Category)\n            .First()\n            .Category;\n\n    public static System.Collections.Generic.List<string> CustomerMatrix(\n        System.Collections.Generic.IEnumerable<Sale> sales,\n        System.Collections.Generic.IEnumerable<string> customers)\n    {\n        var totals = sales.GroupBy(s => s.Customer)\n            .ToDictionary(g => g.Key, g => g.Sum(s => s.Amount));\n        var rows = new System.Collections.Generic.List<string>();\n        foreach (string c in customers)\n            rows.Add(c + \"=\" + totals.GetValueOrDefault(c));\n        return rows;\n    }\n\n    public static string Run(\n        System.Collections.Generic.IEnumerable<Sale> sales,\n        System.Collections.Generic.IEnumerable<string> customers)\n    {\n        var data = sales.ToList();                       // single pull \u2014 everything derives from this\n        decimal revenue = Revenue(data);\n        string best = BestCategory(data);\n        string matrix = string.Join(\"|\", CustomerMatrix(data, customers));\n        return \"revenue=\" + revenue + \";best=\" + best + \";\" + matrix;\n    }\n}\n";
