R["csi-p8-top-customers"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> TopCustomers(IEnumerable<OrderLine> lines, int n)\n    {\n        return lines\n            .GroupBy(l => l.Customer)\n            .Select(g => new { Name = g.Key, Total = g.Sum(l => l.Amount) })\n            .OrderByDescending(x => x.Total)\n            .ThenBy(x => x.Name)\n            .Take(n)\n            .Select(x => x.Name + \": \" + x.Total)\n            .ToList();\n    }\n}\n";
W["csi-p8-top-customers"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> TopCustomers(IEnumerable<OrderLine> lines, int n)\n    {\n        // near-miss: no ThenBy \u2014 OrderByDescending alone is NOT stable for\n        // equal keys in LINQ-to-objects group ordering, so the tie test fails\n        return lines\n            .GroupBy(l => l.Customer)\n            .Select(g => new { Name = g.Key, Total = g.Sum(l => l.Amount) })\n            .OrderByDescending(x => x.Total)\n            .Take(n)\n            .Select(x => x.Name + \": \" + x.Total)\n            .ToList();\n    }\n}\n";
R["csi-p8-group-report"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> DailyReport(IEnumerable<OrderLine> lines)\n    {\n        return lines\n            .GroupBy(l => l.Day)\n            .OrderBy(g => g.Key)\n            .Select(g =>\n            {\n                decimal avg = Math.Round(g.Average(l => l.Amount), 1, MidpointRounding.AwayFromZero);\n                return \"Day \" + g.Key.ToString(\"00\") + \": \" + g.Count() + \" orders, avg \" + avg.ToString(\"0.0\", System.Globalization.CultureInfo.InvariantCulture);\n            })\n            .ToList();\n    }\n}\n";
W["csi-p8-group-report"] = "public class Solution\n{\n    public record OrderLine(string Customer, decimal Amount, int Day);\n\n    public static List<string> DailyReport(IEnumerable<OrderLine> lines)\n    {\n        // near-miss: forgot OrderBy(g => g.Key) \u2014 dictionary-group enumeration\n        // order happens to look sorted for this input but the explicit ordering\n        // contract is broken; the reversed-days test fails\n        return lines\n            .GroupBy(l => l.Day)\n            .Select(g =>\n            {\n                decimal avg = Math.Round(g.Average(l => l.Amount), 1, MidpointRounding.AwayFromZero);\n                return \"Day \" + g.Key.ToString(\"00\") + \": \" + g.Count() + \" orders, avg \" + avg.ToString(\"0.0\", System.Globalization.CultureInfo.InvariantCulture);\n            })\n            .ToList();\n    }\n}\n";
R["csi-p8-double-enum-debug"] = "public class Solution\n{\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<int>\n    {\n        private readonly int[] _items;\n        public CountingSource(params int[] items) => _items = items;\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<int> GetEnumerator()\n        {\n            foreach (int item in _items)\n            {\n                ReadCount++;\n                yield return item;\n            }\n        }\n    }\n\n    public static string Run(System.Collections.Generic.IEnumerable<int> source)\n    {\n        // fixed: ONE enumeration \u2014 materialize first, then aggregate freely\n        var data = source.ToList();\n        int count = data.Count;\n        int max = count > 0 ? data.Max() : 0;\n        return \"count=\" + count + \";max=\" + max;\n    }\n}\n";
W["csi-p8-double-enum-debug"] = "public class Solution\n{\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<int>\n    {\n        private readonly int[] _items;\n        public CountingSource(params int[] items) => _items = items;\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<int> GetEnumerator()\n        {\n            foreach (int item in _items)\n            {\n                ReadCount++;\n                yield return item;\n            }\n        }\n    }\n\n    public static string Run(System.Collections.Generic.IEnumerable<int> source)\n    {\n        // near-miss: still TWO passes over the lazy source \u2014 Count() pulls\n        // everything once, Max() pulls it all again; ReadCount == 12 for the\n        // six-item test\n        int count = source.Count();\n        int max = count > 0 ? source.Max() : 0;\n        return \"count=\" + count + \";max=\" + max;\n    }\n}\n";
