R["csi-p11-container"] = "public class Solution\n{\n    public sealed class Container\n    {\n        private readonly System.Collections.Generic.Dictionary<System.Type, Func<object>> _factories = new();\n\n        public void Register<TService>(Func<TService> factory)\n        {\n            _factories[typeof(TService)] = () => factory()!;\n        }\n\n        public void RegisterSingleton<TService>(Func<TService> factory)\n        {\n            object? instance = null;\n            _factories[typeof(TService)] = () =>\n            {\n                if (instance is null) instance = factory()!;\n                return instance;\n            };\n        }\n\n        public TService Resolve<TService>()\n        {\n            if (!_factories.TryGetValue(typeof(TService), out var factory))\n                throw new System.InvalidOperationException(\n                    \"no registration for \" + typeof(TService).Name);\n            return (TService)factory();\n        }\n    }\n}\n";
W["csi-p11-container"] = "public class Solution\n{\n    public sealed class Container\n    {\n        private readonly System.Collections.Generic.Dictionary<System.Type, Func<object>> _factories = new();\n\n        public void Register<TService>(Func<TService> factory)\n        {\n            _factories[typeof(TService)] = () => factory()!;\n        }\n\n        public void RegisterSingleton<TService>(Func<TService> factory)\n        {\n            // near-miss: the singleton closure forgets its instance \u2014 every\n            // resolve calls the factory again, so built == 2 and the identity\n            // test fails\n            _factories[typeof(TService)] = () => factory()!;\n        }\n\n        public TService Resolve<TService>()\n        {\n            if (!_factories.TryGetValue(typeof(TService), out var factory))\n                throw new System.InvalidOperationException(\"no registration\");\n            return (TService)factory();\n        }\n    }\n}\n";
R["csi-p11-composition-root"] = "public class Solution\n{\n    public interface IClock { System.DateTime Now { get; } }\n\n    public sealed class FakeClock : IClock\n    {\n        private readonly System.DateTime _now;\n        public FakeClock(System.DateTime now) => _now = now;\n        public System.DateTime Now => _now;\n    }\n\n    public interface IPriceCalculator\n    {\n        decimal Quote(decimal basePrice, System.DateTime at);\n    }\n\n    public sealed class RushCalculator : IPriceCalculator\n    {\n        public decimal Quote(decimal basePrice, System.DateTime at)\n        {\n            return at.Hour < 9 ? basePrice * 1.10m : basePrice;\n        }\n    }\n\n    public sealed class App\n    {\n        private readonly IPriceCalculator _calc;\n        private readonly IClock _clock;\n\n        public App(IPriceCalculator calc, IClock clock)\n        {\n            _calc = calc;\n            _clock = clock;\n        }\n\n        public string Quote(decimal p)\n        {\n            return \"total=\" + _calc.Quote(p, _clock.Now);\n        }\n    }\n\n    public static App BuildApp(FakeClock clock)\n    {\n        var container = new Container();\n        container.RegisterSingleton<IClock>(() => clock);\n        container.RegisterTransient<IPriceCalculator>(() => new RushCalculator());\n        return new App(container.Resolve<IPriceCalculator>(), container.Resolve<IClock>());\n    }\n}\n";
