R["csi-p13-status-outcomes"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<string> GetOutcomeAsync(\n        System.Net.Http.HttpClient http, string path,\n        System.Threading.CancellationToken ct = default)\n    {\n        using var resp = await http.GetAsync(path, ct);\n        int code = (int)resp.StatusCode;\n        if (resp.IsSuccessStatusCode)\n            return \"data:\" + await resp.Content.ReadAsStringAsync(ct);\n        if (code == 404) return \"notfound\";\n        if (code == 403) return \"forbidden\";\n        if (code >= 500) return \"servererror\";\n        return \"error:\" + code;\n    }\n}\n";
