R["csi-p13-request-shape"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task PostJsonAsync(\n        System.Net.Http.HttpClient http, string path, string json, string traceId,\n        System.Threading.CancellationToken ct = default)\n    {\n        using var content = new System.Net.Http.StringContent(\n            json, System.Text.Encoding.UTF8, \"application/json\");\n        using var req = new System.Net.Http.HttpRequestMessage(\n            System.Net.Http.HttpMethod.Post, path) { Content = content };\n        req.Headers.Add(\"X-Trace\", traceId);\n        await http.SendAsync(req, ct);\n    }\n}\n";
