R["csi-p15-parameterized-lookup"] = "public class Solution\n{\n    public static string FindUser(CjDb db, string name)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users WHERE name = @name\");\n        cmd.AddParameter(\"@name\", name);\n        var rows = db.ExecuteReader(cmd);\n        return rows.Count > 0 ? \"user:\" + rows[0][\"name\"] : \"notfound\";\n    }\n}\n";
W["csi-p15-parameterized-lookup"] = "public class Solution\n{\n    public static string FindUser(CjDb db, string name)\n    {\n        // near-miss: string-concatenated SQL \u2014 the engine rejects the\n        // unparameterized WHERE (and in a real engine, this is the injection hole)\n        var cmd = db.CreateCommand(\"SELECT * FROM users WHERE name = '\" + name + \"'\");\n        var rows = db.ExecuteReader(cmd);\n        return rows.Count > 0 ? \"user:\" + rows[0][\"name\"] : \"notfound\";\n    }\n}\n";
R["csi-p15-row-mapping"] = "public class Solution\n{\n    public sealed record User(string Name, int Age, decimal Balance);\n\n    private static User Map(System.Collections.Generic.Dictionary<string, object?> row)\n    {\n        return new User(\n            Name: (string)row[\"name\"]!,\n            Age: row.ContainsKey(\"age\") && row[\"age\"] is not null ? Convert.ToInt32(row[\"age\"]) : 0,\n            Balance: row.ContainsKey(\"balance\") && row[\"balance\"] is not null ? Convert.ToDecimal(row[\"balance\"]) : 0m);\n    }\n\n    public static System.Collections.Generic.List<User> LoadUsers(CjDb db)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users\");\n        var rows = db.ExecuteReader(cmd);\n        var users = new System.Collections.Generic.List<User>();\n        foreach (var row in rows) users.Add(Map(row));\n        users.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));\n        return users;\n    }\n}\n";
W["csi-p15-row-mapping"] = "public class Solution\n{\n    public sealed record User(string Name, int Age, decimal Balance);\n\n    public static System.Collections.Generic.List<User> LoadUsers(CjDb db)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users\");\n        var rows = db.ExecuteReader(cmd);\n        var users = new System.Collections.Generic.List<User>();\n        foreach (var row in rows)\n        {\n            // near-miss: no mapping layer \u2014 the raw row dictionary leaks into\n            // the domain and the null-age rule is nowhere\n            users.Add(new User((string)row[\"name\"]!, -1, 0m));\n        }\n        return users;\n    }\n}\n";
R["csi-p15-transaction-debug"] = "public class Solution\n{\n    public static void Transfer(CjDb db, string from, string to)\n    {\n        db.BeginTransaction();\n        try\n        {\n            var debit = db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n            debit.AddParameter(\"@name\", \"-\" + from);\n            db.ExecuteNonQuery(debit);\n\n            var credit = db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n            credit.AddParameter(\"@name\", \"+\" + to);\n            db.ExecuteNonQuery(credit);\n\n            db.CommitTransaction();\n        }\n        catch\n        {\n            throw;   // engine aborts the transaction on failure \u2014 debit is not left alone\n        }\n    }\n}\n";
W["csi-p15-transaction-debug"] = "public class Solution\n{\n    public static void Transfer(CjDb db, string from, string to)\n    {\n        // near-miss: no transaction \u2014 if the credit insert fails, the debit\n        // is already committed: a half-written transfer\n        var debit = db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n        debit.AddParameter(\"@name\", \"-\" + from);\n        db.ExecuteNonQuery(debit);\n\n        var credit = db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n        credit.AddParameter(\"@name\", \"+\" + to);\n        db.ExecuteNonQuery(credit);\n    }\n}\n";
R["csi-checkpoint-m15-task"] = "public class Solution\n{\n    public sealed record User(string Name, decimal Balance);\n\n    public interface IUserRepository\n    {\n        string Register(string name);\n        User? FindByName(string name);\n        int Count();\n    }\n\n    public sealed class SqlUserRepository : IUserRepository\n    {\n        private readonly CjDb _db;\n\n        public SqlUserRepository(CjDb db) => _db = db;\n\n        public string Register(string name)\n        {\n            _db.BeginTransaction();\n            try\n            {\n                var check = _db.CreateCommand(\"SELECT * FROM users WHERE name = @name\");\n                check.AddParameter(\"@name\", name);\n                if (_db.ExecuteReader(check).Count > 0)\n                {\n                    _db.CommitTransaction();\n                    return \"duplicate\";\n                }\n\n                var insert = _db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n                insert.AddParameter(\"@name\", name);\n                _db.ExecuteNonQuery(insert);\n                _db.CommitTransaction();\n                return \"ok\";\n            }\n            catch\n            {\n                throw;   // engine aborts; nothing half-written survives\n            }\n        }\n\n        public User? FindByName(string name)\n        {\n            var cmd = _db.CreateCommand(\"SELECT * FROM users WHERE name = @name\");\n            cmd.AddParameter(\"@name\", name);\n            var rows = _db.ExecuteReader(cmd);\n            return rows.Count > 0 ? Map(rows[0]) : null;\n        }\n\n        public int Count()\n        {\n            var cmd = _db.CreateCommand(\"SELECT * FROM users\");\n            return _db.ExecuteReader(cmd).Count;\n        }\n\n        private static User Map(System.Collections.Generic.Dictionary<string, object?> row)\n        {\n            return new User(\n                Name: (string)row[\"name\"]!,\n                Balance: row.ContainsKey(\"balance\") && row[\"balance\"] is not null\n                    ? Convert.ToDecimal(row[\"balance\"]) : 0m);\n        }\n    }\n\n    public sealed class UserService\n    {\n        private readonly IUserRepository _repo;\n\n        public UserService(IUserRepository repo) => _repo = repo;\n\n        public string Invite(string name)\n        {\n            return _repo.Register(name) == \"ok\" ? \"invited:\" + name : \"exists:\" + name;\n        }\n    }\n}\n";
W["csi-checkpoint-m15-task"] = "public class Solution\n{\n    public sealed record User(string Name, decimal Balance);\n\n    public interface IUserRepository\n    {\n        string Register(string name);\n        User? FindByName(string name);\n        int Count();\n    }\n\n    public sealed class SqlUserRepository : IUserRepository\n    {\n        private readonly CjDb _db;\n\n        public SqlUserRepository(CjDb db) => _db = db;\n\n        public string Register(string name)\n        {\n            // near-miss: NO transaction and NO uniqueness check \u2014 duplicate\n            // names insert happily and Register always returns \"ok\"\n            var insert = _db.CreateCommand(\"INSERT INTO users (name) VALUES (@name)\");\n            insert.AddParameter(\"@name\", name);\n            _db.ExecuteNonQuery(insert);\n            return \"ok\";\n        }\n\n        public User? FindByName(string name)\n        {\n            // near-miss: unparameterized WHERE \u2014 the engine throws\n            // \"unsafe query\" instead of returning a row\n            var cmd = _db.CreateCommand(\"SELECT * FROM users WHERE name = '\" + name + \"'\");\n            var rows = _db.ExecuteReader(cmd);\n            return rows.Count > 0 ? new User((string)rows[0][\"name\"]!, 0m) : null;\n        }\n\n        public int Count()\n        {\n            var cmd = _db.CreateCommand(\"SELECT * FROM users\");\n            return _db.ExecuteReader(cmd).Count;\n        }\n    }\n\n    public sealed class UserService\n    {\n        private readonly IUserRepository _repo;\n\n        public UserService(IUserRepository repo) => _repo = repo;\n\n        public string Invite(string name)\n        {\n            return _repo.Register(name) == \"ok\" ? \"invited:\" + name : \"exists:\" + name;\n        }\n    }\n}\n";
R["csi-p15-parameterized-lookup"] = "public class Solution\n{\n    public static string FindUser(CjDb db, string name)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users WHERE name = @name\");\n        cmd.AddParameter(\"@name\", name);\n        var rows = db.ExecuteReader(cmd);\n        return rows.Count > 0 ? \"user:\" + rows[0][\"name\"] : \"notfound\";\n    }\n}\n";
W["csi-p15-parameterized-lookup"] = "public class Solution\n{\n    public static string FindUser(CjDb db, string name)\n    {\n        // near-miss: string-concatenated SQL \u2014 the engine rejects the\n        // unparameterized WHERE (and in a real engine, this is the injection hole)\n        var cmd = db.CreateCommand(\"SELECT * FROM users WHERE name = '\" + name + \"'\");\n        var rows = db.ExecuteReader(cmd);\n        return rows.Count > 0 ? \"user:\" + rows[0][\"name\"] : \"notfound\";\n    }\n}\n";
R["csi-p15-row-mapping"] = "public class Solution\n{\n    public sealed record User(string Name, int Age, decimal Balance);\n\n    private static User Map(System.Collections.Generic.Dictionary<string, object?> row)\n    {\n        return new User(\n            Name: (string)row[\"name\"]!,\n            Age: row.ContainsKey(\"age\") && row[\"age\"] is not null ? Convert.ToInt32(row[\"age\"]) : 0,\n            Balance: row.ContainsKey(\"balance\") && row[\"balance\"] is not null ? Convert.ToDecimal(row[\"balance\"]) : 0m);\n    }\n\n    public static System.Collections.Generic.List<User> LoadUsers(CjDb db)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users\");\n        var rows = db.ExecuteReader(cmd);\n        var users = new System.Collections.Generic.List<User>();\n        foreach (var row in rows) users.Add(Map(row));\n        users.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));\n        return users;\n    }\n}\n";
W["csi-p15-row-mapping"] = "public class Solution\n{\n    public sealed record User(string Name, int Age, decimal Balance);\n\n    public static System.Collections.Generic.List<User> LoadUsers(CjDb db)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users\");\n        var rows = db.ExecuteReader(cmd);\n        var users = new System.Collections.Generic.List<User>();\n        foreach (var row in rows)\n        {\n            // near-miss: no mapping layer \u2014 the raw row dictionary leaks into\n            // the domain and the null-age rule is nowhere\n            users.Add(new User((string)row[\"name\"]!, -1, 0m));\n        }\n        return users;\n    }\n}\n";
