R["csi-p15-row-mapping"] = "public class Solution\n{\n    public sealed record User(string Name, int Age, decimal Balance);\n\n    private static User Map(System.Collections.Generic.Dictionary<string, object?> row)\n    {\n        return new User(\n            Name: (string)row[\"name\"]!,\n            Age: row.ContainsKey(\"age\") && row[\"age\"] is not null ? Convert.ToInt32(row[\"age\"]) : 0,\n            Balance: row.ContainsKey(\"balance\") && row[\"balance\"] is not null ? Convert.ToDecimal(row[\"balance\"]) : 0m);\n    }\n\n    public static System.Collections.Generic.List<User> LoadUsers(CjDb db)\n    {\n        var cmd = db.CreateCommand(\"SELECT * FROM users\");\n        var rows = db.ExecuteReader(cmd);\n        var users = new System.Collections.Generic.List<User>();\n        foreach (var row in rows) users.Add(Map(row));\n        users.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));\n        return users;\n    }\n}\n";
