W["csi-p18-builder-order"] = "public static class Solution\n{\n    public sealed class OrderReq\n    {\n        public string Customer = \"\";\n        public int TotalQty;\n        public int Items;\n        public bool Rush;\n    }\n\n    public sealed class OrderBuilder\n    {\n        private string _customer = \"\";\n        private int _totalQty;\n        private int _lines;\n        private bool _rush;\n\n        public OrderBuilder WithCustomer(string c)\n        {\n            _customer = c;\n            return this;\n        }\n\n        public OrderBuilder WithItem(string sku, int qty, decimal price)\n        {\n            if (qty < 1) throw new ArgumentException(\"qty must be >= 1\");\n            _totalQty += qty;\n            _lines++;\n            return this;\n        }\n\n        public OrderBuilder WithRush()\n        {\n            _rush = true;\n            return this;\n        }\n\n        public OrderReq Build()\n        {\n            if (string.IsNullOrEmpty(_customer)) throw new InvalidOperationException(\"customer required\");\n            if (_lines == 0) throw new InvalidOperationException(\"at least one item required\");\n            // near-miss: >= instead of > \u2014 10-item rush orders now rejected\n            if (_rush && _totalQty >= 10) throw new InvalidOperationException(\"rush limited to 10 items\");\n            return new OrderReq { Customer = _customer, TotalQty = _totalQty, Items = _lines, Rush = _rush };\n        }\n    }\n\n    public static bool Threw(Action a)\n    {\n        try { a(); return false; }\n        catch { return true; }\n    }\n\n    public static bool RushThrew(int items)\n    {\n        try\n        {\n            var b = new OrderBuilder().WithCustomer(\"ann\").WithRush();\n            for (int i = 0; i < items; i++) b.WithItem(\"s\" + i, 1, 1m);\n            b.Build();\n            return false;\n        }\n        catch { return true; }\n    }\n}\n";
R["csi-p18-observer-review"] = "public static class Solution\n{\n    public sealed class EventBus\n    {\n        private readonly System.Collections.Generic.List<EventHandler<string>> _handlers = new();\n        public int FiredCount;\n\n        public void Subscribe(EventHandler<string> h) => _handlers.Add(h);\n\n        public void Unsubscribe(EventHandler<string> h) => _handlers.Remove(h);\n\n        public void PingAll(string msg)\n        {\n            foreach (var h in _handlers.ToArray())   // snapshot: safe against mutation during fire\n            {\n                h(this, msg);\n                FiredCount++;\n            }\n        }\n    }\n}\n";
W["csi-p18-observer-review"] = "public static class Solution\n{\n    public sealed class EventBus\n    {\n        private readonly System.Collections.Generic.List<EventHandler<string>> _handlers = new();\n        public int FiredCount;\n\n        public void Subscribe(EventHandler<string> h) => _handlers.Add(h);\n\n        // near-miss: \"unsubscribes\" by clearing EVERYONE \u2014 the poisoned fix:\n        // the specific leak is gone, but innocent handlers vanish too\n        public void Unsubscribe(EventHandler<string> h) => _handlers.Clear();\n\n        public void PingAll(string msg)\n        {\n            foreach (var h in _handlers.ToArray())\n            {\n                h(this, msg);\n                FiredCount++;\n            }\n        }\n    }\n}\n";
R["csi-checkpoint-m18-task"] = "public static class Solution\n{\n    public sealed class Order\n    {\n        public string Sku = \"\";\n        public int Qty;\n    }\n\n    public interface IRule\n    {\n        string? Check(Order o);\n    }\n\n    public sealed class MinQty : IRule\n    {\n        public string? Check(Order o) => o.Qty < 2 ? \"qty\" : null;\n    }\n\n    public sealed class PaidSku : IRule\n    {\n        public string? Check(Order o) => string.IsNullOrEmpty(o.Sku) ? \"sku\" : null;\n    }\n\n    public static string? Validate(Order o, IRule[] rules)\n    {\n        foreach (var r in rules)\n        {\n            if (r is null) continue;\n            var err = r.Check(o);\n            if (err is not null) return err;\n        }\n        return null;\n    }\n\n    public interface IRepo\n    {\n        void Save(Order o);\n        int Saved { get; }\n    }\n\n    public sealed class MemRepo : IRepo\n    {\n        public int Saved { get; private set; }\n        public void Save(Order o) => Saved++;\n    }\n\n    public sealed class AuditedRepo : IRepo\n    {\n        private readonly IRepo _inner;\n        public int Saves;\n\n        public AuditedRepo(IRepo inner) => _inner = inner;\n\n        public void Save(Order o)\n        {\n            _inner.Save(o);\n            Saves++;\n        }\n\n        public int Saved => _inner.Saved;\n    }\n}\n";
W["csi-checkpoint-m18-task"] = "public static class Solution\n{\n    public sealed class Order\n    {\n        public string Sku = \"\";\n        public int Qty;\n    }\n\n    public interface IRule\n    {\n        string? Check(Order o);\n    }\n\n    public sealed class MinQty : IRule\n    {\n        // near-miss: inverted comparison \u2014 passes short orders, fails big ones\n        public string? Check(Order o) => o.Qty >= 2 ? \"qty\" : null;\n    }\n\n    public sealed class PaidSku : IRule\n    {\n        public string? Check(Order o) => string.IsNullOrEmpty(o.Sku) ? \"sku\" : null;\n    }\n\n    public static string? Validate(Order o, IRule[] rules)\n    {\n        foreach (var r in rules)\n        {\n            if (r is null) continue;\n            var err = r.Check(o);\n            if (err is not null) return err;\n        }\n        return null;\n    }\n\n    public interface IRepo\n    {\n        void Save(Order o);\n        int Saved { get; }\n    }\n\n    public sealed class MemRepo : IRepo\n    {\n        public int Saved { get; private set; }\n        public void Save(Order o) => Saved++;\n    }\n\n    public sealed class AuditedRepo : IRepo\n    {\n        private readonly IRepo _inner;\n        public int Saves;\n\n        public AuditedRepo(IRepo inner) => _inner = inner;\n\n        public void Save(Order o)\n        {\n            _inner.Save(o);\n            Saves++;\n        }\n\n        public int Saved => _inner.Saved;\n    }\n}\n";
R["csi-p19-port-seam"] = "public static class Solution\n{\n    public const int Delta = 5;\n\n    public interface IStore\n    {\n        int Get(int id);\n        void Put(int id, int v);\n    }\n\n    public sealed class DictStore : IStore\n    {\n        private readonly System.Collections.Generic.Dictionary<int, int> _d;\n        public DictStore(System.Collections.Generic.Dictionary<int, int> d) => _d = d;\n        public int Get(int id) => _d.TryGetValue(id, out var v) ? v : 0;\n        public void Put(int id, int v) => _d[id] = v;\n    }\n\n    public sealed class DoubleStore : IStore\n    {\n        private readonly System.Collections.Generic.Dictionary<int, int> _d = new();\n        public int Get(int id) => _d.TryGetValue(id, out var v) ? v : 0;\n        public void Put(int id, int v) => _d[id] = v;\n    }\n\n    public sealed class Service\n    {\n        private readonly IStore _store;\n        public Service(IStore store) => _store = store;\n\n        public int Bump(int id)\n        {\n            int v = _store.Get(id) + Delta;\n            _store.Put(id, v);\n            return v;\n        }\n    }\n}\n";
W["csi-p19-port-seam"] = "public static class Solution\n{\n    public const int Delta = 5;\n\n    public interface IStore\n    {\n        int Get(int id);\n        void Put(int id, int v);\n    }\n\n    public sealed class DictStore : IStore\n    {\n        private readonly System.Collections.Generic.Dictionary<int, int> _d;\n        public DictStore(System.Collections.Generic.Dictionary<int, int> d) => _d = d;\n        public int Get(int id) => _d.TryGetValue(id, out var v) ? v : 0;\n        public void Put(int id, int v) => _d[id] = v;\n    }\n\n    public sealed class DoubleStore : IStore\n    {\n        private readonly System.Collections.Generic.Dictionary<int, int> _d = new();\n        public int Get(int id) => _d.TryGetValue(id, out var v) ? v : 0;\n        public void Put(int id, int v) => _d[id] = v;\n    }\n\n    public sealed class Service\n    {\n        private readonly IStore _store;\n        public Service(IStore store) => _store = store;\n\n        public int Bump(int id)\n        {\n            // near-miss: re-reads after the put and adds Delta AGAIN \u2014\n            // the port is used, but the arithmetic drifts upward\n            int v = _store.Get(id) + Delta;\n            _store.Put(id, v);\n            return _store.Get(id) + Delta;\n        }\n    }\n}\n";
R["csi-p19-batch-lookup"] = "public interface ILookup\n{\n    string[] FetchMany(int[] ids);\n    int Calls { get; }\n}\n\npublic static class Solution\n{\n    public sealed class Customer\n    {\n        public int Id;\n    }\n\n    public static string[] LoadNames(Customer[] customers, ILookup store)\n    {\n        // distinct ids in first-seen order\n        var order = new System.Collections.Generic.List<int>();\n        var seen = new System.Collections.Generic.HashSet<int>();\n        foreach (var c in customers)\n            if (seen.Add(c.Id)) order.Add(c.Id);\n\n        var fetched = store.FetchMany(order.ToArray());\n\n        var result = new string[customers.Length];\n        var pos = new System.Collections.Generic.Dictionary<int, int>();\n        for (int i = 0; i < customers.Length; i++)\n            if (!pos.ContainsKey(customers[i].Id)) pos[customers[i].Id] = pos.Count;\n        for (int i = 0; i < customers.Length; i++)\n            result[i] = fetched[pos[customers[i].Id]];\n        return result;\n    }\n}\n";
W["csi-p19-batch-lookup"] = "public interface ILookup\n{\n    string[] FetchMany(int[] ids);\n    int Calls { get; }\n}\n\npublic static class Solution\n{\n    public sealed class Customer\n    {\n        public int Id;\n    }\n\n    public static string[] LoadNames(Customer[] customers, ILookup store)\n    {\n        var result = new string[customers.Length];\n        // near-miss: one call PER CUSTOMER \u2014 the N+1 shape, unchanged\n        for (int i = 0; i < customers.Length; i++)\n        {\n            var got = store.FetchMany(new[] { customers[i].Id });\n            result[i] = got[0];\n        }\n        return result;\n    }\n}\n";
R["csi-p19-dto-boundary"] = "public static class Solution\n{\n    public sealed class Employee\n    {\n        public string Name = \"\";\n        public string Dept = \"\";\n        public decimal Salary;\n    }\n\n    public sealed class PublicDto\n    {\n        public string Name = \"\";\n        public string Dept = \"\";\n    }\n\n    public static PublicDto ToPublic(Employee e) =>\n        new PublicDto { Name = e.Name, Dept = e.Dept };\n\n    public static PublicDto[] TeamReport(Employee[] staff)\n    {\n        var rows = new PublicDto[staff.Length];\n        for (int i = 0; i < staff.Length; i++) rows[i] = ToPublic(staff[i]);\n        return rows;\n    }\n\n    public static bool DtoHasSalaryMember() =>\n        typeof(PublicDto).GetMember(\"Salary\").Length > 0;\n}\n";
W["csi-p19-dto-boundary"] = "public static class Solution\n{\n    public sealed class Employee\n    {\n        public string Name = \"\";\n        public string Dept = \"\";\n        public decimal Salary;\n    }\n\n    // near-miss: the DTO exposes the field the boundary exists to hide\n    public sealed class PublicDto\n    {\n        public string Name = \"\";\n        public string Dept = \"\";\n        public decimal Salary;\n    }\n\n    public static PublicDto ToPublic(Employee e) =>\n        new PublicDto { Name = e.Name, Dept = e.Dept, Salary = e.Salary };\n\n    public static PublicDto[] TeamReport(Employee[] staff)\n    {\n        var rows = new PublicDto[staff.Length];\n        for (int i = 0; i < staff.Length; i++) rows[i] = ToPublic(staff[i]);\n        return rows;\n    }\n\n    public static bool DtoHasSalaryMember() =>\n        typeof(PublicDto).GetMember(\"Salary\").Length > 0;\n}\n";
R["csi-p19-n1-debug"] = "public interface ILookup\n{\n    string[] FetchMany(int[] ids);\n    int Calls { get; }\n}\n\npublic static class Solution\n{\n    public static string[] Load(ILookup store, int[] ids)\n    {\n        if (ids.Length == 0) return new string[0];\n\n        // distinct ids in first-seen order; firstPos[id] = its position there\n        var firstPos = new System.Collections.Generic.Dictionary<int, int>();\n        for (int i = 0; i < ids.Length; i++)\n            if (!firstPos.ContainsKey(ids[i])) firstPos[ids[i]] = firstPos.Count;\n\n        var distinct = new int[firstPos.Count];\n        foreach (var kv in firstPos) distinct[kv.Value] = kv.Key;\n\n        var fetched = store.FetchMany(distinct);\n\n        var outp = new string[ids.Length];\n        for (int i = 0; i < ids.Length; i++)\n            outp[i] = fetched[firstPos[ids[i]]];\n        return outp;\n    }\n}\n";
W["csi-p19-n1-debug"] = "public interface ILookup\n{\n    string[] FetchMany(int[] ids);\n    int Calls { get; }\n}\n\npublic static class Solution\n{\n    public static string[] Load(ILookup store, int[] ids)\n    {\n        if (ids.Length == 0) return new string[0];\n\n        var outp = new string[ids.Length];\n        // near-miss: dedups but still one CALL per distinct id \u2014 N calls, not 1\n        for (int i = 0; i < ids.Length; i++)\n        {\n            bool seen = false;\n            for (int j = 0; j < i; j++) seen |= ids[j] == ids[i];\n            if (!seen) outp[i] = store.FetchMany(new[] { ids[i] })[0];\n        }\n        for (int i = 1; i < ids.Length; i++)\n            if (outp[i] is null) outp[i] = outp[i - 1];\n        return outp;\n    }\n}\n";
