W["csi-p20-stringbuilder"] = "public static class Solution\n{\n    public static string Report(string[] lines)\n    {\n        var s = \"\";\n        // near-miss: still allocates per iteration \u2014 builds via += but\n        // wraps it so it *looks* like a builder\n        var sb = new System.Text.StringBuilder();\n        foreach (var line in lines)\n        {\n            s += line + \"\\n\";\n            sb.Append(s[s.Length - 1]);   // fake \"use\" of the builder\n        }\n        StringOps.Bump();\n        return s;\n    }\n}\n";
R["csi-p20-set-membership"] = "public static class Solution\n{\n    public static bool HasAny(\n        System.Collections.Generic.List<int> haystack,\n        System.Collections.Generic.List<int> needles)\n    {\n        var set = new System.Collections.Generic.HashSet<int>(haystack);\n        foreach (var n in needles)\n            if (set.Contains(n)) return true;\n        return false;\n    }\n}\n";
W["csi-p20-set-membership"] = "public static class Solution\n{\n    public static bool HasAny(\n        System.Collections.Generic.List<int> haystack,\n        System.Collections.Generic.List<int> needles)\n    {\n        // near-miss: builds the set but still scans the LIST per needle \u2014\n        // the set exists, the quadratic shape does too\n        var set = new System.Collections.Generic.HashSet<int>(haystack);\n        foreach (var n in needles)\n            foreach (var h in haystack)\n                if (h == n && set.Contains(n)) return true;\n        return false;\n    }\n}\n";
R["csi-p20-materialize"] = "public static class Solution\n{\n    public sealed class Stats { public int Count; public string Joined = \"\"; }\n\n    public static Stats Heavy(int[] source)\n    {\n        var snapshot = new System.Collections.Generic.List<int>();\n        foreach (var x in source)\n            if (x % 2 == 0) snapshot.Add(x);\n\n        var joined = new System.Text.StringBuilder();\n        for (int i = 0; i < snapshot.Count; i++)\n        {\n            if (i > 0) joined.Append('|');\n            joined.Append(snapshot[i]);\n        }\n        return new Stats { Count = snapshot.Count, Joined = joined.ToString() };\n    }\n}\n";
W["csi-p20-materialize"] = "public static class Solution\n{\n    public sealed class Stats { public int Count; public string Joined = \"\"; }\n\n    public static Stats Heavy(int[] source)\n    {\n        // near-miss: two separate enumerations of the source \u2014 count first,\n        // then join. Same answers, wrong shape.\n        int count = 0;\n        foreach (var x in source) if (x % 2 == 0) count++;\n\n        var joined = new System.Text.StringBuilder();\n        bool first = true;\n        foreach (var x in source)\n            if (x % 2 == 0)\n            {\n                if (!first) joined.Append('|');\n                first = false;\n                joined.Append(x);\n            }\n        return new Stats { Count = count, Joined = joined.ToString() };\n    }\n}\n";
R["csi-p20-hotloop-debug"] = "public static class Solution\n{\n    public static System.Func<string, string> BuildChecker(\n        System.Collections.Generic.List<string> catalog)\n    {\n        var known = new System.Collections.Generic.HashSet<string>(catalog);\n        int cheap = 0;\n        foreach (var s in catalog)\n            if (s.Length < 4) cheap++;\n\n        return sku =>\n        {\n            if (known.Contains(sku)) return \"known\";\n            return cheap > 0 ? \"cheap-others\" : \"unknown\";\n        };\n    }\n}\n";
W["csi-p20-hotloop-debug"] = "public static class Solution\n{\n    public static System.Func<string, string> BuildChecker(\n        System.Collections.Generic.List<string> catalog)\n    {\n        var known = new System.Collections.Generic.HashSet<string>(catalog);\n\n        return sku =>\n        {\n            if (known.Contains(sku)) return \"known\";\n            // near-miss: the \"expensive\" count is still recomputed per call \u2014\n            // the loop moved out of sight, not out of the hot path\n            int cheap = 0;\n            foreach (var s in catalog)\n                if (s.Length < 4) cheap++;\n            return cheap > 0 ? \"cheap-others\" : \"unknown\";\n        };\n    }\n}\n";
R["csi-checkpoint-m20-task"] = "public static class Solution\n{\n    public sealed class PriceBook\n    {\n        private readonly int[] _prices;\n        public int LookupCount { get; private set; }\n\n        public PriceBook(int[] prices) => _prices = (int[])prices.Clone();\n\n        public int Total(int[] skus)\n        {\n            int t = 0;\n            foreach (var s in skus) t += _prices[s];\n            return t;\n        }\n\n        public int Lookup(int sku)\n        {\n            LookupCount++;\n            return _prices[sku];\n        }\n    }\n\n    public static int[] TopSkus(int[] skus, int take)\n    {\n        var freq = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var s in skus)\n            freq[s] = freq.TryGetValue(s, out var c) ? c + 1 : 1;\n\n        var ordered = new System.Collections.Generic.List<int>(freq.Keys);\n        ordered.Sort((a, b) =>\n        {\n            int byFreq = freq[b].CompareTo(freq[a]);\n            return byFreq != 0 ? byFreq : a.CompareTo(b);\n        });\n\n        int n = ordered.Count < take ? ordered.Count : take;\n        var outp = new int[n];\n        for (int i = 0; i < n; i++) outp[i] = ordered[i];\n        return outp;\n    }\n\n    public static string Summary(int[] skus)\n    {\n        var top = TopSkus(skus, skus.Length);\n        var joined = new System.Text.StringBuilder();\n        for (int i = 0; i < top.Length; i++)\n        {\n            if (i > 0) joined.Append(',');\n            joined.Append(top[i]);\n        }\n        return top.Length + \":\" + joined;\n    }\n}\n";
W["csi-checkpoint-m20-task"] = "public static class Solution\n{\n    public sealed class PriceBook\n    {\n        private readonly int[] _prices;\n        public int LookupCount { get; private set; }\n\n        public PriceBook(int[] prices) => _prices = (int[])prices.Clone();\n\n        public int Total(int[] skus)\n        {\n            // near-miss: \"Total\" implemented as N counted single-sku lookups \u2014\n            // the per-call cost the whole module exists to remove\n            int t = 0;\n            foreach (var s in skus) t += Lookup(s);\n            return t;\n        }\n\n        public int Lookup(int sku)\n        {\n            LookupCount++;\n            return _prices[sku];\n        }\n    }\n\n    public static int[] TopSkus(int[] skus, int take)\n    {\n        var freq = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var s in skus)\n            freq[s] = freq.TryGetValue(s, out var c) ? c + 1 : 1;\n\n        var ordered = new System.Collections.Generic.List<int>(freq.Keys);\n        ordered.Sort((a, b) =>\n        {\n            int byFreq = freq[b].CompareTo(freq[a]);\n            return byFreq != 0 ? byFreq : a.CompareTo(b);\n        });\n\n        int n = ordered.Count < take ? ordered.Count : take;\n        var outp = new int[n];\n        for (int i = 0; i < n; i++) outp[i] = ordered[i];\n        return outp;\n    }\n\n    public static string Summary(int[] skus)\n    {\n        var top = TopSkus(skus, skus.Length);\n        var joined = new System.Text.StringBuilder();\n        for (int i = 0; i < top.Length; i++)\n        {\n            if (i > 0) joined.Append(',');\n            joined.Append(top[i]);\n        }\n        return top.Length + \":\" + joined;\n    }\n}\n";
