W["csi-p20-stringbuilder"] = "public static class Solution\n{\n    public static string Report(string[] lines)\n    {\n        var s = \"\";\n        // near-miss: still allocates per iteration \u2014 builds via += but\n        // wraps it so it *looks* like a builder\n        var sb = new System.Text.StringBuilder();\n        foreach (var line in lines)\n        {\n            s += line + \"\\n\";\n            sb.Append(s[s.Length - 1]);   // fake \"use\" of the builder\n        }\n        StringOps.Bump();\n        return s;\n    }\n}\n";
R["csi-p20-set-membership"] = "public static class Solution\n{\n    public static bool HasAny(\n        System.Collections.Generic.List<int> haystack,\n        System.Collections.Generic.List<int> needles)\n    {\n        var set = new System.Collections.Generic.HashSet<int>(haystack);\n        foreach (var n in needles)\n            if (set.Contains(n)) return true;\n        return false;\n    }\n}\n";
W["csi-p20-set-membership"] = "public static class Solution\n{\n    public static bool HasAny(\n        System.Collections.Generic.List<int> haystack,\n        System.Collections.Generic.List<int> needles)\n    {\n        // near-miss: builds the set but still scans the LIST per needle \u2014\n        // the set exists, the quadratic shape does too\n        var set = new System.Collections.Generic.HashSet<int>(haystack);\n        foreach (var n in needles)\n            foreach (var h in haystack)\n                if (h == n && set.Contains(n)) return true;\n        return false;\n    }\n}\n";
R["csi-p20-materialize"] = "public static class Solution\n{\n    public sealed class Stats { public int Count; public string Joined = \"\"; }\n\n    public static Stats Heavy(int[] source)\n    {\n        var snapshot = new System.Collections.Generic.List<int>();\n        foreach (var x in source)\n            if (x % 2 == 0) snapshot.Add(x);\n\n        var joined = new System.Text.StringBuilder();\n        for (int i = 0; i < snapshot.Count; i++)\n        {\n            if (i > 0) joined.Append('|');\n            joined.Append(snapshot[i]);\n        }\n        return new Stats { Count = snapshot.Count, Joined = joined.ToString() };\n    }\n}\n";
W["csi-p20-materialize"] = "public static class Solution\n{\n    public sealed class Stats { public int Count; public string Joined = \"\"; }\n\n    public static Stats Heavy(int[] source)\n    {\n        // near-miss: two separate enumerations of the source \u2014 count first,\n        // then join. Same answers, wrong shape.\n        int count = 0;\n        foreach (var x in source) if (x % 2 == 0) count++;\n\n        var joined = new System.Text.StringBuilder();\n        bool first = true;\n        foreach (var x in source)\n            if (x % 2 == 0)\n            {\n                if (!first) joined.Append('|');\n                first = false;\n                joined.Append(x);\n            }\n        return new Stats { Count = count, Joined = joined.ToString() };\n    }\n}\n";
