W["csi-checkpoint-m20-task"] = "public static class Solution\n{\n    public sealed class PriceBook\n    {\n        private readonly int[] _prices;\n        public int LookupCount { get; private set; }\n\n        public PriceBook(int[] prices) => _prices = (int[])prices.Clone();\n\n        public int Total(int[] skus)\n        {\n            // near-miss: \"Total\" implemented as N counted single-sku lookups \u2014\n            // the per-call cost the whole module exists to remove\n            int t = 0;\n            foreach (var s in skus) t += Lookup(s);\n            return t;\n        }\n\n        public int Lookup(int sku)\n        {\n            LookupCount++;\n            return _prices[sku];\n        }\n    }\n\n    public static int[] TopSkus(int[] skus, int take)\n    {\n        var freq = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var s in skus)\n            freq[s] = freq.TryGetValue(s, out var c) ? c + 1 : 1;\n\n        var ordered = new System.Collections.Generic.List<int>(freq.Keys);\n        ordered.Sort((a, b) =>\n        {\n            int byFreq = freq[b].CompareTo(freq[a]);\n            return byFreq != 0 ? byFreq : a.CompareTo(b);\n        });\n\n        int n = ordered.Count < take ? ordered.Count : take;\n        var outp = new int[n];\n        for (int i = 0; i < n; i++) outp[i] = ordered[i];\n        return outp;\n    }\n\n    public static string Summary(int[] skus)\n    {\n        var top = TopSkus(skus, skus.Length);\n        var joined = new System.Text.StringBuilder();\n        for (int i = 0; i < top.Length; i++)\n        {\n            if (i > 0) joined.Append(',');\n            joined.Append(top[i]);\n        }\n        return top.Length + \":\" + joined;\n    }\n}\n";
R["csi-p21-param-query"] = "public static class Solution\n{\n    public static (string Sql, string Value) BuildLoginQuery(string username)\n    {\n        // the value travels as data; the SQL keeps a placeholder\n        return (\"SELECT * FROM Users WHERE Name = @p0\", username);\n    }\n}\n";
W["csi-p21-param-query"] = "public static class Solution\n{\n    public static (string Sql, string Value) BuildLoginQuery(string username)\n    {\n        // near-miss: \"escaped\" the input but still pastes it into query text \u2014\n        // quoting is data-mangling, not a parameter\n        var safe = username.Replace(\"'\", \"''\");\n        return (\"SELECT * FROM Users WHERE Name = '\" + safe + \"'\", username);\n    }\n}\n";
R["csi-p21-path-safe"] = "public static class Solution\n{\n    public static string SafeResolve(string baseDir, string userPath)\n    {\n        if (string.IsNullOrEmpty(userPath)) return null;\n        var baseFull = System.IO.Path.GetFullPath(baseDir);\n        var full = System.IO.Path.GetFullPath(\n            System.IO.Path.Combine(baseFull, userPath));\n        var allowedPrefix = baseFull.EndsWith(\n            System.IO.Path.DirectorySeparatorChar.ToString())\n            ? baseFull\n            : baseFull + System.IO.Path.DirectorySeparatorChar;\n        if (!full.StartsWith(allowedPrefix)) return null;\n        if (full == baseFull) return null;\n        return full;\n    }\n}\n";
W["csi-p21-path-safe"] = "public static class Solution\n{\n    public static string SafeResolve(string baseDir, string userPath)\n    {\n        // near-miss: blocks the *string* \"../\" but never resolves the path \u2014\n        // encoded or composed escapes slip through, and nothing is confined\n        if (userPath.Contains(\"..\")) return null;\n        return System.IO.Path.Combine(baseDir, userPath);\n    }\n}\n";
R["csi-p21-password-hash"] = "public static class Solution\n{\n    public static void RequireSalt(byte[] salt)\n    {\n        if (salt == null || salt.Length < 16)\n            throw new System.ArgumentException(\"salt must be at least 16 bytes\");\n    }\n\n    public static string HashPassword(string password, byte[] salt)\n    {\n        RequireSalt(salt);\n        return KdfShape.Hex(KdfShape.Derive(password, salt, 100_000));\n    }\n\n    public static bool Verify(string password, byte[] salt, string storedHex)\n    {\n        if (salt == null || salt.Length < 16 || storedHex == null) return false;\n        return KdfShape.Hex(KdfShape.Derive(password, salt, 100_000)) == storedHex;\n    }\n}\n";
W["csi-p21-password-hash"] = "public static class Solution\n{\n    public static void RequireSalt(byte[] salt)\n    {\n        if (salt == null || salt.Length < 16)\n            throw new System.ArgumentException(\"salt must be at least 16 bytes\");\n    }\n\n    public static string HashPassword(string password, byte[] salt)\n    {\n        RequireSalt(salt);\n        // near-miss: validates the salt, then hashes with a bare fast digest \u2014\n        // no KDF, no iterations; the shape is right, the crypto is wrong\n        using var sha = System.Security.Cryptography.SHA256.Create();\n        var bytes = System.Text.Encoding.UTF8.GetBytes(password);\n        return KdfShape.Hex(sha.ComputeHash(bytes));\n    }\n\n    public static bool Verify(string password, byte[] salt, string storedHex)\n    {\n        if (salt == null || salt.Length < 16 || storedHex == null) return false;\n        using var sha = System.Security.Cryptography.SHA256.Create();\n        return KdfShape.Hex(sha.ComputeHash(\n            System.Text.Encoding.UTF8.GetBytes(password))) == storedHex;\n    }\n}\n";
R["csi-p21-log-scrub"] = "public static class Solution\n{\n    public static string Audit(string action, string email)\n    {\n        // identity is never echoed; absence of identity is fine\n        return action + \" email=***\";\n    }\n}\n";
W["csi-p21-log-scrub"] = "public static class Solution\n{\n    public static string Audit(string action, string email)\n    {\n        // near-miss: masks when the email \"looks like\" an email \u2014 everything\n        // else (ids, names, anything at all) is pasted raw\n        if (email != null && email.Contains(\"@\"))\n            return action + \" email=***\";\n        return action + \" email=\" + (email ?? \"\");\n    }\n}\n";
R["csi-checkpoint-m21-task"] = "public static class Solution\n{\n    private static readonly System.Collections.Generic.Dictionary<string, (byte[] Salt, string Hash)> Users\n        = new System.Collections.Generic.Dictionary<string, (byte[], string)>();\n\n    private static void Require(byte[] salt)\n    {\n        if (salt == null || salt.Length < 16)\n            throw new System.ArgumentException(\"salt must be at least 16 bytes\");\n    }\n\n    public static void Register(string username, string password, byte[] salt)\n    {\n        Require(salt);\n        if (Users.ContainsKey(username))\n            throw new System.InvalidOperationException(\"user exists\");\n        Users[username] = (salt, KdfShape.Hex(KdfShape.Derive(password, salt, 100_000)));\n    }\n\n    public static bool Validate(string username, string password)\n    {\n        if (!Users.TryGetValue(username, out var rec)) return false;\n        return KdfShape.Hex(KdfShape.Derive(password, rec.Salt, 100_000)) == rec.Hash;\n    }\n\n    public static string HashOf(string username)\n    {\n        return Users.TryGetValue(username, out var rec) ? rec.Hash : null;\n    }\n\n    public static string FindUsername(string raw)\n    {\n        // input is data: an exact dictionary lookup, no query text involved\n        return Users.ContainsKey(raw) ? raw : null;\n    }\n\n    public static string OpenFile(string baseDir, string userPath)\n    {\n        if (string.IsNullOrEmpty(userPath)) return null;\n        var baseFull = System.IO.Path.GetFullPath(baseDir);\n        var full = System.IO.Path.GetFullPath(\n            System.IO.Path.Combine(baseFull, userPath));\n        var prefix = baseFull.EndsWith(System.IO.Path.DirectorySeparatorChar.ToString())\n            ? baseFull\n            : baseFull + System.IO.Path.DirectorySeparatorChar;\n        if (!full.StartsWith(prefix) || full == baseFull) return null;\n        return full;\n    }\n}\n";
W["csi-checkpoint-m21-task"] = "public static class Solution\n{\n    private static readonly System.Collections.Generic.Dictionary<string, string> Users\n        = new System.Collections.Generic.Dictionary<string, string>();\n\n    public static void Register(string username, string password, byte[] salt)\n    {\n        if (Users.ContainsKey(username))\n            throw new System.InvalidOperationException(\"user exists\");\n        // near-miss: validates the salt, then ignores it \u2014 hashes depend only\n        // on the password, so identical passwords collide across users\n        if (salt == null || salt.Length < 16)\n            throw new System.ArgumentException(\"salt must be at least 16 bytes\");\n        Users[username] = KdfShape.Hex(KdfShape.Derive(password, new byte[16], 100_000));\n    }\n\n    public static bool Validate(string username, string password)\n    {\n        if (!Users.TryGetValue(username, out var hash)) return false;\n        return KdfShape.Hex(KdfShape.Derive(password, new byte[16], 100_000)) == hash;\n    }\n\n    public static string HashOf(string username)\n    {\n        return Users.TryGetValue(username, out var hash) ? hash : null;\n    }\n\n    public static string FindUsername(string raw)\n    {\n        return Users.ContainsKey(raw) ? raw : null;\n    }\n\n    public static string OpenFile(string baseDir, string userPath)\n    {\n        // near-miss: string-level rejection, no resolution, no confinement\n        if (userPath != null && userPath.Contains(\"..\")) return null;\n        return System.IO.Path.Combine(baseDir, userPath ?? \"\");\n    }\n}\n";
R["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        DomainGuard.Defined(status);\n        return title.Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
W["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        // near-miss: checks length but not null/whitespace, and trusts the\n        // enum cast without Enum.IsDefined\n        if (title != null && title.Length > 120)\n            throw new System.ArgumentException(\"title too long\");\n        return (title ?? \"\").Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
R["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            if (!_items.ContainsKey(task.Id)) return false;\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
W["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            // near-miss: reports success without checking existence \u2014 silently\n            // inserting a task the store never issued, ids and all\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
R["csi-p22-service-authz"] = "public static class Solution\n{\n    private sealed record User(int Id, string Name, Role Role);\n    private static readonly System.Collections.Generic.Dictionary<int, User> _users\n        = new System.Collections.Generic.Dictionary<int, User>();\n    private static readonly System.Collections.Generic.Dictionary<int, Project> _projects\n        = new System.Collections.Generic.Dictionary<int, Project>();\n    private static readonly System.Collections.Generic.Dictionary<int, TaskItem> _tasks\n        = new System.Collections.Generic.Dictionary<int, TaskItem>();\n    private static int _nextTask = 1;\n\n    public static void Register(int id, string name, Role role)\n        => _users[id] = new User(id, name, role);\n\n    public static void AddProject(int id, string name, int ownerId)\n        => _projects[id] = new Project(id, name, ownerId);\n\n    public static int CreateTask(int callerId, int projectId, string title, Priority priority)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        if (!_users.ContainsKey(callerId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"caller\");\n        if (!_projects.TryGetValue(projectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        var t = new TaskItem(_nextTask, projectId, title.Trim(), null, priority, Status.Todo);\n        _tasks[t.Id] = t;\n        _nextTask++;\n        return t.Id;\n    }\n\n    public static void Assign(int callerId, int taskId, int assigneeId)\n    {\n        if (!_users.ContainsKey(callerId) || !_users.ContainsKey(assigneeId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"user\");\n        if (!_tasks.TryGetValue(taskId, out var task))\n            throw new System.Collections.Generic.KeyNotFoundException(\"task\");\n        if (!_projects.TryGetValue(task.ProjectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        _tasks[taskId] = task with { AssigneeId = assigneeId };\n    }\n\n    public static TaskItem? FindTask(int taskId)\n        => _tasks.TryGetValue(taskId, out var t) ? t : null;\n}\n";
W["csi-p22-service-authz"] = "public static class Solution\n{\n    private sealed record User(int Id, string Name, Role Role);\n    private static readonly System.Collections.Generic.Dictionary<int, User> _users\n        = new System.Collections.Generic.Dictionary<int, User>();\n    private static readonly System.Collections.Generic.Dictionary<int, Project> _projects\n        = new System.Collections.Generic.Dictionary<int, Project>();\n    private static readonly System.Collections.Generic.Dictionary<int, TaskItem> _tasks\n        = new System.Collections.Generic.Dictionary<int, TaskItem>();\n    private static int _nextTask = 1;\n\n    public static void Register(int id, string name, Role role)\n        => _users[id] = new User(id, name, role);\n\n    public static void AddProject(int id, string name, int ownerId)\n        => _projects[id] = new Project(id, name, ownerId);\n\n    public static int CreateTask(int callerId, int projectId, string title, Priority priority)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        if (!_users.ContainsKey(callerId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"caller\");\n        if (!_projects.TryGetValue(projectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        // near-miss: the authorization check asks the wrong question \u2014 it\n        // lets anyone who is *not* the owner through instead of only owners\n        // and admins\n        if (!(project.OwnerId != callerId && _users[callerId].Role != Role.Admin))\n            throw new System.InvalidOperationException(\"not allowed\");\n        var t = new TaskItem(_nextTask, projectId, title.Trim(), null, priority, Status.Todo);\n        _tasks[t.Id] = t;\n        _nextTask++;\n        return t.Id;\n    }\n\n    public static void Assign(int callerId, int taskId, int assigneeId)\n    {\n        if (!_users.ContainsKey(callerId) || !_users.ContainsKey(assigneeId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"user\");\n        if (!_tasks.TryGetValue(taskId, out var task))\n            throw new System.Collections.Generic.KeyNotFoundException(\"task\");\n        if (!_projects.TryGetValue(task.ProjectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        _tasks[taskId] = task with { AssigneeId = assigneeId };\n    }\n\n    public static TaskItem? FindTask(int taskId)\n        => _tasks.TryGetValue(taskId, out var t) ? t : null;\n}\n";
R["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                if (t.Status == Status.Done) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
W["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                // near-miss: InProgress tasks are counted as Done \u2014 the\n                // report flatters the project and the burn-down lies\n                if (t.Status != Status.Todo) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
R["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            if (ct.IsCancellationRequested)\n                throw new System.OperationCanceledException(ct);\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            _nextId++;\n            return _store.PutAsync(item, ct).ContinueWith(_ => item.Id);\n        }\n    }\n\n    public static Service BuildEngine(Solution.FakeStore store) => new Service(store);\n}\n";
W["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            // near-miss: stores first, checks cancellation after \u2014 a cancelled\n            // caller still has its item persisted (and gets no exception)\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            _nextId++;\n            var put = _store.PutAsync(item, ct);\n            if (ct.IsCancellationRequested)\n                throw new System.OperationCanceledException(ct);\n            return put.ContinueWith(_ => item.Id);\n        }\n    }\n\n    public static Service BuildEngine(Solution.FakeStore store) => new Service(store);\n}\n";
R["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        DomainGuard.Defined(status);\n        return title.Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
W["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        // near-miss: checks length but not null/whitespace, and trusts the\n        // enum cast without Enum.IsDefined\n        if (title != null && title.Length > 120)\n            throw new System.ArgumentException(\"title too long\");\n        return (title ?? \"\").Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
R["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            if (!_items.ContainsKey(task.Id)) return false;\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
W["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            // near-miss: reports success without checking existence \u2014 silently\n            // inserting a task the store never issued, ids and all\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
R["csi-p22-service-authz"] = "public static class Solution\n{\n    private sealed record User(int Id, string Name, Role Role);\n    private static readonly System.Collections.Generic.Dictionary<int, User> _users\n        = new System.Collections.Generic.Dictionary<int, User>();\n    private static readonly System.Collections.Generic.Dictionary<int, Project> _projects\n        = new System.Collections.Generic.Dictionary<int, Project>();\n    private static readonly System.Collections.Generic.Dictionary<int, TaskItem> _tasks\n        = new System.Collections.Generic.Dictionary<int, TaskItem>();\n    private static int _nextTask = 1;\n\n    public static void Register(int id, string name, Role role)\n        => _users[id] = new User(id, name, role);\n\n    public static void AddProject(int id, string name, int ownerId)\n        => _projects[id] = new Project(id, name, ownerId);\n\n    public static int CreateTask(int callerId, int projectId, string title, Priority priority)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        if (!_users.ContainsKey(callerId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"caller\");\n        if (!_projects.TryGetValue(projectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        var t = new TaskItem(_nextTask, projectId, title.Trim(), null, priority, Status.Todo);\n        _tasks[t.Id] = t;\n        _nextTask++;\n        return t.Id;\n    }\n\n    public static void Assign(int callerId, int taskId, int assigneeId)\n    {\n        if (!_users.ContainsKey(callerId) || !_users.ContainsKey(assigneeId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"user\");\n        if (!_tasks.TryGetValue(taskId, out var task))\n            throw new System.Collections.Generic.KeyNotFoundException(\"task\");\n        if (!_projects.TryGetValue(task.ProjectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        _tasks[taskId] = task with { AssigneeId = assigneeId };\n    }\n\n    public static TaskItem? FindTask(int taskId)\n        => _tasks.TryGetValue(taskId, out var t) ? t : null;\n}\n";
W["csi-p22-service-authz"] = "public static class Solution\n{\n    private sealed record User(int Id, string Name, Role Role);\n    private static readonly System.Collections.Generic.Dictionary<int, User> _users\n        = new System.Collections.Generic.Dictionary<int, User>();\n    private static readonly System.Collections.Generic.Dictionary<int, Project> _projects\n        = new System.Collections.Generic.Dictionary<int, Project>();\n    private static readonly System.Collections.Generic.Dictionary<int, TaskItem> _tasks\n        = new System.Collections.Generic.Dictionary<int, TaskItem>();\n    private static int _nextTask = 1;\n\n    public static void Register(int id, string name, Role role)\n        => _users[id] = new User(id, name, role);\n\n    public static void AddProject(int id, string name, int ownerId)\n        => _projects[id] = new Project(id, name, ownerId);\n\n    public static int CreateTask(int callerId, int projectId, string title, Priority priority)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        if (!_users.ContainsKey(callerId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"caller\");\n        if (!_projects.TryGetValue(projectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        // near-miss: the authorization check asks the wrong question \u2014 it\n        // lets anyone who is *not* the owner through instead of only owners\n        // and admins\n        if (!(project.OwnerId != callerId && _users[callerId].Role != Role.Admin))\n            throw new System.InvalidOperationException(\"not allowed\");\n        var t = new TaskItem(_nextTask, projectId, title.Trim(), null, priority, Status.Todo);\n        _tasks[t.Id] = t;\n        _nextTask++;\n        return t.Id;\n    }\n\n    public static void Assign(int callerId, int taskId, int assigneeId)\n    {\n        if (!_users.ContainsKey(callerId) || !_users.ContainsKey(assigneeId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"user\");\n        if (!_tasks.TryGetValue(taskId, out var task))\n            throw new System.Collections.Generic.KeyNotFoundException(\"task\");\n        if (!_projects.TryGetValue(task.ProjectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        _tasks[taskId] = task with { AssigneeId = assigneeId };\n    }\n\n    public static TaskItem? FindTask(int taskId)\n        => _tasks.TryGetValue(taskId, out var t) ? t : null;\n}\n";
