W["csi-p22-service-authz"] = "public static class Solution\n{\n    private sealed record User(int Id, string Name, Role Role);\n    private static readonly System.Collections.Generic.Dictionary<int, User> _users\n        = new System.Collections.Generic.Dictionary<int, User>();\n    private static readonly System.Collections.Generic.Dictionary<int, Project> _projects\n        = new System.Collections.Generic.Dictionary<int, Project>();\n    private static readonly System.Collections.Generic.Dictionary<int, TaskItem> _tasks\n        = new System.Collections.Generic.Dictionary<int, TaskItem>();\n    private static int _nextTask = 1;\n\n    public static void Register(int id, string name, Role role)\n        => _users[id] = new User(id, name, role);\n\n    public static void AddProject(int id, string name, int ownerId)\n        => _projects[id] = new Project(id, name, ownerId);\n\n    public static int CreateTask(int callerId, int projectId, string title, Priority priority)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        if (!_users.ContainsKey(callerId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"caller\");\n        if (!_projects.TryGetValue(projectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        // near-miss: the authorization check asks the wrong question \u2014 it\n        // lets anyone who is *not* the owner through instead of only owners\n        // and admins\n        if (!(project.OwnerId != callerId && _users[callerId].Role != Role.Admin))\n            throw new System.InvalidOperationException(\"not allowed\");\n        var t = new TaskItem(_nextTask, projectId, title.Trim(), null, priority, Status.Todo);\n        _tasks[t.Id] = t;\n        _nextTask++;\n        return t.Id;\n    }\n\n    public static void Assign(int callerId, int taskId, int assigneeId)\n    {\n        if (!_users.ContainsKey(callerId) || !_users.ContainsKey(assigneeId))\n            throw new System.Collections.Generic.KeyNotFoundException(\"user\");\n        if (!_tasks.TryGetValue(taskId, out var task))\n            throw new System.Collections.Generic.KeyNotFoundException(\"task\");\n        if (!_projects.TryGetValue(task.ProjectId, out var project))\n            throw new System.Collections.Generic.KeyNotFoundException(\"project\");\n        if (project.OwnerId != callerId && _users[callerId].Role != Role.Admin)\n            throw new System.InvalidOperationException(\"not allowed\");\n        _tasks[taskId] = task with { AssigneeId = assigneeId };\n    }\n\n    public static TaskItem? FindTask(int taskId)\n        => _tasks.TryGetValue(taskId, out var t) ? t : null;\n}\n";
R["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                if (t.Status == Status.Done) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
W["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                // near-miss: InProgress tasks are counted as Done \u2014 the\n                // report flatters the project and the burn-down lies\n                if (t.Status != Status.Todo) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
R["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            if (ct.IsCancellationRequested)\n                throw new System.OperationCanceledException(ct);\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            _nextId++;\n            return _store.PutAsync(item, ct).ContinueWith(_ => item.Id);\n        }\n    }\n\n    public static Service BuildEngine(FakeStore store) => new Service(store);\n}\n";
W["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            // near-miss: stores first, checks cancellation after \u2014 a cancelled\n            // caller still has its item persisted (and gets no exception)\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            _nextId++;\n            var put = _store.PutAsync(item, ct);\n            if (ct.IsCancellationRequested)\n                throw new System.OperationCanceledException(ct);\n            return put.ContinueWith(_ => item.Id);\n        }\n    }\n\n    public static Service BuildEngine(FakeStore store) => new Service(store);\n}\n";
R["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        DomainGuard.ValidTitle(title);\n        DomainGuard.Defined(priority);\n        DomainGuard.Defined(status);\n        return title.Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
W["csi-p22-domain"] = "public static class Solution\n{\n    public static string ValidateTaskInput(string title, Priority priority, Status status)\n    {\n        // near-miss: checks length but not null/whitespace, and trusts the\n        // enum cast without Enum.IsDefined\n        if (title != null && title.Length > 120)\n            throw new System.ArgumentException(\"title too long\");\n        return (title ?? \"\").Trim();\n    }\n\n    public static TaskItem NewTask(int id, int projectId, string title, Priority priority)\n    {\n        var clean = ValidateTaskInput(title, priority, Status.Todo);\n        return new TaskItem(id, projectId, clean, null, priority, Status.Todo);\n    }\n}\n";
R["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            if (!_items.ContainsKey(task.Id)) return false;\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
W["csi-p22-repository"] = "public static class Solution\n{\n    public interface ITaskRepo\n    {\n        int NextId();\n        TaskItem Add(int projectId, string title, Priority priority);\n        bool TryFind(int id, out TaskItem task);\n        bool Update(TaskItem task);\n        System.Collections.Generic.IReadOnlyList<TaskItem> All();\n    }\n\n    public sealed class TaskRepo : ITaskRepo\n    {\n        private readonly System.Collections.Generic.Dictionary<int, TaskItem> _items\n            = new System.Collections.Generic.Dictionary<int, TaskItem>();\n        private int _next = 1;\n\n        public int NextId() => _next;\n\n        public TaskItem Add(int projectId, string title, Priority priority)\n        {\n            var t = new TaskItem(_next, projectId, title, null, priority, Status.Todo);\n            _items[_next] = t;\n            _next++;\n            return t;\n        }\n\n        public bool TryFind(int id, out TaskItem task)\n            => _items.TryGetValue(id, out task);\n\n        public bool Update(TaskItem task)\n        {\n            // near-miss: reports success without checking existence \u2014 silently\n            // inserting a task the store never issued, ids and all\n            _items[task.Id] = task;\n            return true;\n        }\n\n        public System.Collections.Generic.IReadOnlyList<TaskItem> All()\n            => new System.Collections.Generic.List<TaskItem>(_items.Values);\n    }\n}\n";
