R["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                if (t.Status == Status.Done) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
W["csi-p22-reporting"] = "public static class Solution\n{\n    public static System.Collections.Generic.List<string> Progress(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var rows = new System.Collections.Generic.List<string>();\n        var projects = new System.Collections.Generic.SortedSet<int>();\n        foreach (var t in tasks) projects.Add(t.ProjectId);\n        foreach (var p in projects)\n        {\n            int open = 0, done = 0;\n            foreach (var t in tasks)\n            {\n                if (t.ProjectId != p) continue;\n                // near-miss: InProgress tasks are counted as Done \u2014 the\n                // report flatters the project and the burn-down lies\n                if (t.Status != Status.Todo) done++; else open++;\n            }\n            rows.Add(\"P\" + p + \":\" + open + \":\" + done);\n        }\n        return rows;\n    }\n\n    public static System.Collections.Generic.List<int> Backlog(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks, Priority priority)\n    {\n        var ids = new System.Collections.Generic.List<int>();\n        foreach (var t in tasks)\n            if (t.Priority == priority && t.Status != Status.Done) ids.Add(t.Id);\n        ids.Sort();\n        return ids;\n    }\n\n    public static System.Collections.Generic.Dictionary<int, int> Workload(\n        System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var counts = new System.Collections.Generic.Dictionary<int, int>();\n        foreach (var t in tasks)\n        {\n            if (t.AssigneeId == null || t.Status == Status.Done) continue;\n            int a = t.AssigneeId.Value;\n            counts[a] = counts.TryGetValue(a, out var c) ? c + 1 : 1;\n        }\n        return counts;\n    }\n}\n";
R["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            foreach (var t in store.Seeds) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            if (ct.IsCancellationRequested)\n                throw new System.OperationCanceledException(ct);\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            return _store.PutAsync(item, ct).ContinueWith(t =>\n            {\n                if (t.IsFaulted) throw t.Exception.InnerException ?? t.Exception;\n                if (ct.IsCancellationRequested)\n                    throw new System.OperationCanceledException(ct);\n                _nextId++;\n                return item.Id;\n            });\n        }\n    }\n\n    public static Service BuildEngine(FakeStore store) => new Service(store);\n}\n";
W["csi-checkpoint-m22-task"] = "public static class Solution\n{\n    private static int _next = 1;\n\n    public static string Snapshot(System.Collections.Generic.IReadOnlyList<TaskItem> tasks)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Serialize(tasks, opts);\n    }\n\n    public static TaskItem[] Load(string json)\n    {\n        var opts = new System.Text.Json.JsonSerializerOptions\n        {\n            PropertyNameCaseInsensitive = true,\n            Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() },\n        };\n        return System.Text.Json.JsonSerializer.Deserialize<TaskItem[]>(json, opts)\n            ?? new TaskItem[0];\n    }\n\n    public sealed class Service\n    {\n        private readonly FakeStore _store;\n        private int _nextId;\n\n        public Service(FakeStore store)\n        {\n            _store = store;\n            int max = 0;\n            foreach (var t in store.Puts) if (t.Id > max) max = t.Id;\n            foreach (var t in store.Seeds) if (t.Id > max) max = t.Id;\n            _nextId = max + 1;\n        }\n\n        public System.Threading.Tasks.Task<int> CreateAsync(\n            int projectId, string title, Priority priority,\n            System.Threading.CancellationToken ct)\n        {\n            DomainGuard.ValidTitle(title);\n            // near-miss: stores first, never observes the result \u2014 cancelled\n            // callers still persist (no exception) and store failures vanish\n            var item = new TaskItem(_nextId, projectId, title.Trim(), null, priority, Status.Todo);\n            _nextId++;\n            return _store.PutAsync(item, ct).ContinueWith(_ => item.Id);\n        }\n    }\n\n    public static Service BuildEngine(FakeStore store) => new Service(store);\n}\n";
R["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a > 0 && b > 0;\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        if (depth <= 0 || groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        if (depth > 1)\n        {\n            total += FlattenDepth(groups, depth - 1) == total ? 0 : 0;\n        }\n        return total;\n    }\n}\n";
W["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        // near-miss: forgot to assign out params on the early-return paths \u2014\n        // the compiler rejects this shape, so the W here instead accepts zero\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a >= 0 && b >= 0;   // near-miss: zero passes\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        // near-miss: no depth bound \u2014 recursion never terminates on the\n        // depth>=1 path unless the arrays are empty, so the deep test hangs\n        if (groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        return total + FlattenDepth(groups, depth - 1);\n    }\n}\n";
R["csi-checkpoint-m3-task"] = "public class Solution\n{\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        int total = seed;\n        return add => total += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
W["csi-checkpoint-m3-task"] = "public class Solution\n{\n    // near-miss: ONE static total shared by all accumulators \u2014 the\n    // independence test fails because acc2 keeps counting acc1's total\n    private static int _shared;\n\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        _shared = seed;\n        return add => _shared += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
R["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n            _nextId++;\n            if (filter is null || filter(message))\n            {\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, args);\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
W["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            // near-miss: the id counter only advances for ACCEPTED messages,\n            // so the filtered publish reuses n-1 and later ids shift\n            if (filter is null || filter(message))\n            {\n                var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n                _nextId++;\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, new NotificationEventArgs(\"n-\" + _nextId, channel, message));\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
R["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() => _items.Values.OrderBy(e => e.Id).ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
W["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() =>\n            // near-miss: insertion order, not Id order \u2014 the \"ordered by id\"\n            // test fails after a delete reshuffles expectations\n            _items.Values.ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
R["csi-checkpoint-m6-task"] = "public class Solution\n{\n    public static IReadOnlyDictionary<string, int> Frequency(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        return counts;\n    }\n\n    public static string? FirstUnique(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        var order = new List<string>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            if (!counts.ContainsKey(word)) order.Add(word);\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        foreach (string word in order)\n            if (counts[word] == 1) return word;\n        return null;\n    }\n\n    public static string ProcessOrders(IEnumerable<string> commands)\n    {\n        var queue = new Queue<string>();\n        var popped = new List<string>();\n        foreach (string command in commands)\n        {\n            if (command == \"pop\")\n            {\n                if (queue.Count > 0) popped.Add(queue.Dequeue());\n            }\n            else if (command.StartsWith(\"push \"))\n            {\n                queue.Enqueue(command.Substring(5));\n            }\n        }\n        return string.Join(\",\", popped);\n    }\n\n    public sealed class EvictCache\n    {\n        private readonly int _capacity;\n        private readonly Dictionary<string, int> _values = new();\n        private readonly List<string> _recency = new();\n\n        public EvictCache(int capacity) => _capacity = capacity;\n\n        public void Put(string key, int value)\n        {\n            if (_values.ContainsKey(key)) _recency.Remove(key);\n            else if (_values.Count >= _capacity)\n            {\n                string oldest = _recency[0];\n                _recency.RemoveAt(0);\n                _values.Remove(oldest);\n            }\n            _values[key] = value;\n            _recency.Add(key);\n        }\n\n        public int Get(string key)\n        {\n            if (!_values.TryGetValue(key, out int v)) return -1;\n            _recency.Remove(key);\n            _recency.Add(key);\n            return v;\n        }\n    }\n}\n";
W["csi-checkpoint-m6-task"] = "public class Solution\n{\n    public static IReadOnlyDictionary<string, int> Frequency(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        return counts;\n    }\n\n    public static string? FirstUnique(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        // near-miss: dictionary order is insertion order here, but the walk\n        // returns the first word with count 1 WITHOUT preserving first-seen\n        // order when a later duplicate re-adds \u2014 the mixed-case test breaks\n        foreach (var pair in counts)\n            if (pair.Value == 1) return pair.Key;\n        return null;\n    }\n\n    public static string ProcessOrders(IEnumerable<string> commands)\n    {\n        var stack = new Stack<string>();\n        var popped = new List<string>();\n        foreach (string command in commands)\n        {\n            if (command == \"pop\")\n            {\n                if (stack.Count > 0) popped.Add(stack.Pop());\n            }\n            else if (command.StartsWith(\"push \"))\n            {\n                stack.Push(command.Substring(5));\n            }\n        }\n        return string.Join(\",\", popped);\n    }\n\n    public sealed class EvictCache\n    {\n        private readonly int _capacity;\n        private readonly Dictionary<string, int> _values = new();\n\n        public EvictCache(int capacity) => _capacity = capacity;\n\n        public void Put(string key, int value)\n        {\n            if (_values.Count >= _capacity)\n            {\n                // near-miss: removes an ARBITRARY (first) key, not the least\n                // recently used \u2014 \"a survives\" fails after the refresh path\n                string victim = new List<string>(_values.Keys)[0];\n                _values.Remove(victim);\n            }\n            _values[key] = value;\n        }\n\n        public int Get(string key) =>\n            _values.TryGetValue(key, out int v) ? v : -1;\n    }\n}\n";
R["csi-checkpoint-m7-task"] = "public class Solution\n{\n    public static IEnumerable<(int Level, string Msg)> ParseLines(IEnumerable<string> lines)\n    {\n        foreach (string line in lines)\n        {\n            string[] parts = line.Split('|');\n            int level = parts[0] switch\n            {\n                \"DEBUG\" => 0,\n                \"INFO\" => 1,\n                \"WARN\" => 2,\n                \"ERROR\" => 3,\n                _ => 0,\n            };\n            yield return (level, parts[1]);\n        }\n    }\n\n    public static IEnumerable<(int Level, string Msg)> FilterLevel(\n        IEnumerable<(int Level, string Msg)> src, int minLevel)\n    {\n        foreach (var entry in src)\n            if (entry.Level >= minLevel) yield return entry;\n    }\n\n    public static IEnumerable<string> Format(IEnumerable<(int Level, string Msg)> src)\n    {\n        foreach (var entry in src)\n            yield return \"[\" + entry.Level + \"] \" + entry.Msg;\n    }\n\n    public static List<string> Run(IEnumerable<string> lines, int minLevel, int maxResults)\n    {\n        var output = new List<string>();\n        foreach (string formatted in Format(FilterLevel(ParseLines(lines), minLevel)))\n        {\n            output.Add(formatted);\n            if (output.Count >= maxResults) break;   // stop pulling from the source\n        }\n        return output;\n    }\n\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<string>\n    {\n        private readonly string[] _lines;\n\n        public CountingSource(params string[] lines) => _lines = lines;\n\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<string> GetEnumerator()\n        {\n            foreach (string line in _lines)\n            {\n                ReadCount++;\n                yield return line;\n            }\n        }\n    }\n}\n";
W["csi-checkpoint-m7-task"] = "public class Solution\n{\n    public static IEnumerable<(int Level, string Msg)> ParseLines(IEnumerable<string> lines)\n    {\n        foreach (string line in lines)\n        {\n            string[] parts = line.Split('|');\n            int level = parts[0] switch\n            {\n                \"DEBUG\" => 0,\n                \"INFO\" => 1,\n                \"WARN\" => 2,\n                \"ERROR\" => 3,\n                _ => 0,\n            };\n            yield return (level, parts[1]);\n        }\n    }\n\n    public static IEnumerable<(int Level, string Msg)> FilterLevel(\n        IEnumerable<(int Level, string Msg)> src, int minLevel)\n    {\n        foreach (var entry in src)\n            if (entry.Level >= minLevel) yield return entry;\n    }\n\n    public static IEnumerable<string> Format(IEnumerable<(int Level, string Msg)> src)\n    {\n        foreach (var entry in src)\n            yield return \"[\" + entry.Level + \"] \" + entry.Msg;\n    }\n\n    public static List<string> Run(IEnumerable<string> lines, int minLevel, int maxResults)\n    {\n        // near-miss: materializes the WHOLE pipeline before capping \u2014 the\n        // source is drained completely, so the laziness test fails\n        var everything = Format(FilterLevel(ParseLines(lines), minLevel)).ToList();\n        return everything.Take(maxResults).ToList();\n    }\n\n    public sealed class CountingSource : System.Collections.Generic.IEnumerable<string>\n    {\n        private readonly string[] _lines;\n\n        public CountingSource(params string[] lines) => _lines = lines;\n\n        public int ReadCount { get; private set; }\n\n        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();\n\n        public System.Collections.Generic.IEnumerator<string> GetEnumerator()\n        {\n            foreach (string line in _lines)\n            {\n                ReadCount++;\n                yield return line;\n            }\n        }\n    }\n}\n";
R["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a > 0 && b > 0;\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        if (depth <= 0 || groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        if (depth > 1)\n        {\n            total += FlattenDepth(groups, depth - 1) == total ? 0 : 0;\n        }\n        return total;\n    }\n}\n";
W["csi-checkpoint-m2-task"] = "public class Solution\n{\n    private static int _swaps;\n\n    public static bool TrySplitRatio(string input, out int a, out int b)\n    {\n        // near-miss: forgot to assign out params on the early-return paths \u2014\n        // the compiler rejects this shape, so the W here instead accepts zero\n        a = 0; b = 0;\n        if (string.IsNullOrEmpty(input)) return false;\n        string[] parts = input.Split(':');\n        if (parts.Length != 2) return false;\n        if (!int.TryParse(parts[0], out a)) return false;\n        if (!int.TryParse(parts[1], out b)) return false;\n        return a >= 0 && b >= 0;   // near-miss: zero passes\n    }\n\n    public static int SwapWithCount(ref int x, ref int y)\n    {\n        (x, y) = (y, x);\n        _swaps++;\n        return _swaps;\n    }\n\n    public static long FlattenDepth(object[][] groups, int depth)\n    {\n        // near-miss: no depth bound \u2014 recursion never terminates on the\n        // depth>=1 path unless the arrays are empty, so the deep test hangs\n        if (groups is null) return 0;\n        long total = 0;\n        foreach (object[] group in groups)\n        {\n            foreach (object item in group)\n            {\n                if (item is int n) total += n;\n            }\n        }\n        return total + FlattenDepth(groups, depth - 1);\n    }\n}\n";
R["csi-checkpoint-m3-task"] = "public class Solution\n{\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        int total = seed;\n        return add => total += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
W["csi-checkpoint-m3-task"] = "public class Solution\n{\n    // near-miss: ONE static total shared by all accumulators \u2014 the\n    // independence test fails because acc2 keeps counting acc1's total\n    private static int _shared;\n\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        _shared = seed;\n        return add => _shared += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
R["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n            _nextId++;\n            if (filter is null || filter(message))\n            {\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, args);\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
W["csi-checkpoint-m4-task"] = "public class Solution\n{\n    public sealed record NotificationEventArgs(string Id, string Channel, string Message);\n\n    public class NotificationCenter\n    {\n        public event EventHandler<NotificationEventArgs>? Published;\n        public event EventHandler<NotificationEventArgs>? Filtered;\n\n        private int _nextId = 1;\n\n        public void Publish(string channel, string message, Predicate<string>? filter)\n        {\n            // near-miss: the id counter only advances for ACCEPTED messages,\n            // so the filtered publish reuses n-1 and later ids shift\n            if (filter is null || filter(message))\n            {\n                var args = new NotificationEventArgs(\"n-\" + _nextId, channel, message);\n                _nextId++;\n                Published?.Invoke(this, args);\n            }\n            else\n            {\n                Filtered?.Invoke(this, new NotificationEventArgs(\"n-\" + _nextId, channel, message));\n            }\n        }\n\n        public void UnsubscribeAll()\n        {\n            Published = null;\n            Filtered = null;\n        }\n    }\n}\n";
R["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() => _items.Values.OrderBy(e => e.Id).ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
W["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() =>\n            // near-miss: insertion order, not Id order \u2014 the \"ordered by id\"\n            // test fails after a delete reshuffles expectations\n            _items.Values.ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
R["csi-checkpoint-m6-task"] = "public class Solution\n{\n    public static IReadOnlyDictionary<string, int> Frequency(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        return counts;\n    }\n\n    public static string? FirstUnique(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        var order = new List<string>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            if (!counts.ContainsKey(word)) order.Add(word);\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        foreach (string word in order)\n            if (counts[word] == 1) return word;\n        return null;\n    }\n\n    public static string ProcessOrders(IEnumerable<string> commands)\n    {\n        var queue = new Queue<string>();\n        var popped = new List<string>();\n        foreach (string command in commands)\n        {\n            if (command == \"pop\")\n            {\n                if (queue.Count > 0) popped.Add(queue.Dequeue());\n            }\n            else if (command.StartsWith(\"push \"))\n            {\n                queue.Enqueue(command.Substring(5));\n            }\n        }\n        return string.Join(\",\", popped);\n    }\n\n    public sealed class EvictCache\n    {\n        private readonly int _capacity;\n        private readonly Dictionary<string, int> _values = new();\n        private readonly List<string> _recency = new();\n\n        public EvictCache(int capacity) => _capacity = capacity;\n\n        public void Put(string key, int value)\n        {\n            if (_values.ContainsKey(key)) _recency.Remove(key);\n            else if (_values.Count >= _capacity)\n            {\n                string oldest = _recency[0];\n                _recency.RemoveAt(0);\n                _values.Remove(oldest);\n            }\n            _values[key] = value;\n            _recency.Add(key);\n        }\n\n        public int Get(string key)\n        {\n            if (!_values.TryGetValue(key, out int v)) return -1;\n            _recency.Remove(key);\n            _recency.Add(key);\n            return v;\n        }\n    }\n}\n";
