R["csi-checkpoint-m3-task"] = "public class Solution\n{\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        int total = seed;\n        return add => total += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
W["csi-checkpoint-m3-task"] = "public class Solution\n{\n    // near-miss: ONE static total shared by all accumulators \u2014 the\n    // independence test fails because acc2 keeps counting acc1's total\n    private static int _shared;\n\n    public static Func<int, int> MakeAccumulator(int seed)\n    {\n        _shared = seed;\n        return add => _shared += add;\n    }\n\n    public static Action SumActions(params Action?[] steps)\n    {\n        return () =>\n        {\n            foreach (Action? step in steps)\n            {\n                step?.Invoke();\n            }\n        };\n    }\n\n    private static readonly Dictionary<string, Func<int, int>> Commands = new();\n\n    public static void RegisterCommand(string name, Func<int, int> fn)\n    {\n        Commands[name] = fn;\n    }\n\n    public static int Route(string command, int value)\n    {\n        return Commands.TryGetValue(command, out Func<int, int>? fn) ? fn(value) : -1;\n    }\n}\n";
R["csi-p3-shared-counter"] = "public class Solution\n{\n    public static Func<int> MakeCounter()\n    {\n        int count = 0;                 // per-instance: the closure owns it\n        return () => ++count;\n    }\n}";
W["csi-p3-shared-counter"] = "public class Solution\n{\n    // near-miss: the count lives in a STATIC field \u2014 every \"instance\"\n    // shares one counter, so c2 starts where c1 stopped\n    private static int _shared;\n\n    public static Func<int> MakeCounter()\n    {\n        return () => ++_shared;\n    }\n}";
R["csi-p3-loop-capture-debug"] = "public class Solution\n{\n    public static List<Func<int>> Build(int n)\n    {\n        var result = new List<Func<int>>();\n        for (int index = 0; index < n; index++)\n        {\n            int i = index;             // fresh variable per iteration\n            result.Add(() => i);\n        }\n        return result;\n    }\n\n    public static int Sum(List<Func<int>> fs)\n    {\n        int total = 0;\n        foreach (var f in fs) total += f();\n        return total;\n    }\n}";
