R["csi-p4-broadcaster"] = "public class Solution\n{\n    public class Broadcaster\n    {\n        public event EventHandler<string>? Message;\n\n        public void Publish(string message) => Message?.Invoke(this, message);\n    }\n}\n";
W["csi-p4-broadcaster"] = "public class Solution\n{\n    public class Broadcaster\n    {\n        public event EventHandler<string>? Message;\n\n        public void Publish(string message)\n        {\n            // near-miss: invokes a SNAPSHOT taken before the multicast \u2014\n            // a subscriber that joins during the raise misses this publish\n            var handlers = Message;\n            Message?.Invoke(this, message);\n            handlers?.Invoke(this, \"echo:\" + message);\n        }\n    }\n}\n";
R["csi-p4-telemetry"] = "public class Solution\n{\n    public sealed record ReadingEventArgs(string Channel, double Value);\n\n    public class TelemetrySource\n    {\n        public event EventHandler<ReadingEventArgs>? Reading;\n\n        public void Emit(string channel, double value)\n            => Reading?.Invoke(this, new ReadingEventArgs(channel, value));\n\n        public int SubscriberCount => Reading?.GetInvocationList().Length ?? 0;\n    }\n}\n";
W["csi-p4-telemetry"] = "public class Solution\n{\n    public sealed record ReadingEventArgs(string Channel, double Value);\n\n    public class TelemetrySource\n    {\n        private EventHandler<ReadingEventArgs>? _reading;\n\n        public event EventHandler<ReadingEventArgs>? Reading\n        {\n            add { _reading = value; }        // near-miss: assignment, not +=\n            remove { _reading -= value; }\n        }\n\n        public void Emit(string channel, double value)\n            => _reading?.Invoke(this, new ReadingEventArgs(channel, value));\n\n        public int SubscriberCount => _reading?.GetInvocationList().Length ?? 0;\n    }\n}\n";
