R["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() => _items.Values.OrderBy(e => e.Id).ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
W["csi-checkpoint-m5-task"] = "public class Solution\n{\n    public abstract class Entity<TId>\n    {\n        public abstract TId Id { get; }\n    }\n\n    public sealed class User : Entity<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public override int Id { get; }\n        public string Name { get; }\n    }\n\n    public sealed class Order : Entity<string>\n    {\n        public Order(string id, decimal total) { Id = id; Total = total; }\n        public override string Id { get; }\n        public decimal Total { get; }\n    }\n\n    public class DataStore<TId, TEntity>\n        where TEntity : Entity<TId>\n        where TId : IComparable<TId>\n    {\n        private readonly Dictionary<TId, TEntity> _items = new();\n\n        public void Add(TEntity entity) => _items[entity.Id] = entity;\n\n        public TEntity? Get(TId id) => _items.TryGetValue(id, out TEntity? e) ? e : default;\n\n        public bool Delete(TId id) => _items.Remove(id);\n\n        public List<TEntity> AllOrdered() =>\n            // near-miss: insertion order, not Id order \u2014 the \"ordered by id\"\n            // test fails after a delete reshuffles expectations\n            _items.Values.ToList();\n\n        public TEntity? FirstMatching(Predicate<TEntity> match)\n        {\n            foreach (TEntity e in _items.Values)\n                if (match(e)) return e;\n            return default;\n        }\n    }\n}\n";
R["csi-p5-max"] = "public class Solution\n{\n    public static T? Max<T>(T? a, T? b) where T : IComparable<T>\n    {\n        if (a is null) return b;\n        if (b is null) return a;\n        return a.CompareTo(b) >= 0 ? a : b;\n    }\n}\n";
W["csi-p5-max"] = "public class Solution\n{\n    // near-miss: compares via object.Equals \u2014 values that compare equal\n    // (2.50 vs 2.5) hit the wrong branch, and CompareTo ordering is ignored\n    public static T? Max<T>(T? a, T? b) where T : IComparable<T>\n    {\n        if (a is null) return b;\n        if (b is null) return a;\n        return a.Equals(b) ? a : b;\n    }\n}\n";
R["csi-p5-repository"] = "public class Solution\n{\n    public interface IHasId<int> { int Id { get; } }\n\n    public class User : IHasId<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public int Id { get; }\n        public string Name { get; }\n    }\n\n    public class Repository<T> where T : IHasId<int>\n    {\n        private readonly Dictionary<int, T> _items = new();\n\n        public void Add(T entity) => _items[entity.Id] = entity;\n\n        public T? Get(int id) => _items.TryGetValue(id, out var e) ? e : default;\n\n        public int Count => _items.Count;\n\n        public IReadOnlyCollection<T> All() => _items.Values.ToList();\n    }\n}\n";
W["csi-p5-repository"] = "public class Solution\n{\n    public interface IHasId<int> { int Id { get; } }\n\n    public class User : IHasId<int>\n    {\n        public User(int id, string name) { Id = id; Name = name; }\n        public int Id { get; }\n        public string Name { get; }\n    }\n\n    public class Repository<T> where T : IHasId<int>\n    {\n        private readonly List<T> _items = new();\n\n        public void Add(T entity)\n        {\n            // near-miss: Add appends \u2014 re-adding the same Id duplicates\n            // instead of replacing\n            _items.Add(entity);\n        }\n\n        public T? Get(int id)\n        {\n            foreach (var e in _items)\n                if (e.Id == id) return e;\n            return default;\n        }\n\n        public int Count => _items.Count;\n\n        public IReadOnlyCollection<T> All() => _items;\n    }\n}\n";
