W["csi-checkpoint-m6-task"] = "public class Solution\n{\n    public static IReadOnlyDictionary<string, int> Frequency(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        return counts;\n    }\n\n    public static string? FirstUnique(string text)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string raw in text.Split(' ', System.StringSplitOptions.RemoveEmptyEntries))\n        {\n            string word = raw.ToLowerInvariant();\n            counts[word] = System.Collections.Generic.CollectionExtensions.GetValueOrDefault(counts, word) + 1;\n        }\n        // near-miss: dictionary order is insertion order here, but the walk\n        // returns the first word with count 1 WITHOUT preserving first-seen\n        // order when a later duplicate re-adds \u2014 the mixed-case test breaks\n        foreach (var pair in counts)\n            if (pair.Value == 1) return pair.Key;\n        return null;\n    }\n\n    public static string ProcessOrders(IEnumerable<string> commands)\n    {\n        var stack = new Stack<string>();\n        var popped = new List<string>();\n        foreach (string command in commands)\n        {\n            if (command == \"pop\")\n            {\n                if (stack.Count > 0) popped.Add(stack.Pop());\n            }\n            else if (command.StartsWith(\"push \"))\n            {\n                stack.Push(command.Substring(5));\n            }\n        }\n        return string.Join(\",\", popped);\n    }\n\n    public sealed class EvictCache\n    {\n        private readonly int _capacity;\n        private readonly Dictionary<string, int> _values = new();\n\n        public EvictCache(int capacity) => _capacity = capacity;\n\n        public void Put(string key, int value)\n        {\n            if (_values.Count >= _capacity)\n            {\n                // near-miss: removes an ARBITRARY (first) key, not the least\n                // recently used \u2014 \"a survives\" fails after the refresh path\n                string victim = new List<string>(_values.Keys)[0];\n                _values.Remove(victim);\n            }\n            _values[key] = value;\n        }\n\n        public int Get(string key) =>\n            _values.TryGetValue(key, out int v) ? v : -1;\n    }\n}\n";
