R["csi-p7-evens"] = "public class Solution\n{\n    public static IEnumerable<int> EvensUpTo(int n)\n    {\n        for (int i = 0; i <= n; i += 2) yield return i;\n    }\n\n    public static IEnumerable<int> TakeEvens(IEnumerable<int> source, int count)\n    {\n        int taken = 0;\n        foreach (var v in source)\n        {\n            if (taken >= count) yield break;\n            yield return v;\n            taken++;\n        }\n    }\n}\n";
